		rec("bswap", "byte swap", "\u0431\u0430\u0439\u0442 \u0441\u0432\u043e\u043f", "\u043f\u0435\u0440\u0435\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0431\u0430\u0439\u0442\u044b", "\u041f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0431\u0430\u0439\u0442\u043e\u0432 \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0435: 12 34 56 78 \u2192 78 56 34 12. \u0422\u0430\u043a \u043f\u0435\u0440\u0435\u0432\u043e\u0434\u044f\u0442 \u0447\u0438\u0441\u043b\u0430 \u043c\u0435\u0436\u0434\u0443 \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u043c \u0431\u0430\u0439\u0442\u043e\u0432 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430 \u0438 \u0441\u0435\u0442\u0435\u0432\u044b\u043c (3.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0431\u0430\u0439\u0442\u043e\u0432", "3.7");
		rec("bt", "bit test", "\u0431\u0438\u0442 \u0442\u044d\u0441\u0442", "\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0431\u0438\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0431\u0438\u0442 \u043d\u043e\u043c\u0435\u0440 n \u0432 \u0444\u043b\u0430\u0433 CF. \u0421\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 jc (\u043e\u043d \u0436\u0435 jb) \u043f\u0440\u044b\u0433\u043d\u0435\u0442, \u0435\u0441\u043b\u0438 \u0431\u0438\u0442 \u0431\u044b\u043b 1.", "CF = \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u0431\u0438\u0442", "\u0431\u0438\u0442 \u043d\u043e\u043c\u0435\u0440 n \u2192 CF", "9.6");
		rec("btc", "bit test and complement", "\u0431\u0438\u0442 \u0442\u044d\u0441\u0442 \u044d\u043d\u0434 \u043a\u043e\u043c\u043f\u043b\u0438\u043c\u044d\u043d\u0442", "\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0438 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0431\u0438\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0431\u0438\u0442 \u043d\u043e\u043c\u0435\u0440 n \u0432 CF \u0438 \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u044d\u0442\u043e\u0442 \u0431\u0438\u0442.", "CF = \u0441\u0442\u0430\u0440\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0438\u0442\u0430", "\u0431\u0438\u0442 \u2192 CF, \u043f\u043e\u0442\u043e\u043c \u0431\u0438\u0442 \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442", "9.6");
		rec("btr", "bit test and reset", "\u0431\u0438\u0442 \u0442\u044d\u0441\u0442 \u044d\u043d\u0434 \u0440\u0438\u0441\u044d\u0442", "\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0438 \u0441\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0431\u0438\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0431\u0438\u0442 \u043d\u043e\u043c\u0435\u0440 n \u0432 CF \u0438 \u0441\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u044d\u0442\u043e\u0442 \u0431\u0438\u0442 \u0432 0.", "CF = \u0441\u0442\u0430\u0440\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0438\u0442\u0430", "\u0431\u0438\u0442 \u2192 CF, \u043f\u043e\u0442\u043e\u043c \u0431\u0438\u0442 = 0", "9.6");
		rec("bts", "bit test and set", "\u0431\u0438\u0442 \u0442\u044d\u0441\u0442 \u044d\u043d\u0434 \u0441\u044d\u0442", "\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0431\u0438\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0431\u0438\u0442 \u043d\u043e\u043c\u0435\u0440 n \u0432 CF \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 \u044d\u0442\u043e\u0442 \u0431\u0438\u0442 \u0432 1.", "CF = \u0441\u0442\u0430\u0440\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0438\u0442\u0430", "\u0431\u0438\u0442 \u2192 CF, \u043f\u043e\u0442\u043e\u043c \u0431\u0438\u0442 = 1", "9.6");
		rec("call", "call", "\u043a\u043e\u043b", "\u0432\u044b\u0437\u0432\u0430\u0442\u044c", "\u0412\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u0444\u0443\u043d\u043a\u0446\u0438\u044e: \u043a\u043b\u0430\u0434\u0451\u0442 \u043d\u0430 \u0441\u0442\u0435\u043a \u0430\u0434\u0440\u0435\u0441 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 (\u0430\u0434\u0440\u0435\u0441 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0430) \u0438 \u043f\u0440\u044b\u0433\u0430\u0435\u0442 \u0432 \u0444\u0443\u043d\u043a\u0446\u0438\u044e. call \u0447\u0435\u0440\u0435\u0437 qword ptr [...] \u2014 \u043e\u0431\u044b\u0447\u043d\u043e \u0432\u044b\u0437\u043e\u0432 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 WinAPI \u0447\u0435\u0440\u0435\u0437 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438\u043c\u043f\u043e\u0440\u0442\u0430 (12.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u044b\u0437\u043e\u0432 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 (\u0430\u0434\u0440\u0435\u0441 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0430 \u2192 \u0441\u0442\u0435\u043a)", "11.2");
		rec("cbw", "convert byte to word", "\u0441\u0438-\u0431\u0438-\u0434\u0430\u0431\u043b-\u044e", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0431\u0430\u0439\u0442 \u0434\u043e \u0441\u043b\u043e\u0432\u0430", "\u0420\u0430\u0441\u0448\u0438\u0440\u044f\u0435\u0442 AL \u0434\u043e AX \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c. \u0412\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0440\u0435\u0434\u043a\u043e.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "AL \u2192 AX \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "20.4");
		rec("cdq", "convert doubleword to quadword", "\u0441\u0438-\u0434\u0438-\u043a\u044c\u044e", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0434\u0432\u043e\u0439\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0434\u043e \u0447\u0435\u0442\u0432\u0435\u0440\u043d\u043e\u0433\u043e", "\u0417\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 EDX \u0437\u043d\u0430\u043a\u043e\u043c EAX: \u043d\u0443\u043b\u044f\u043c\u0438, \u0435\u0441\u043b\u0438 EAX \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439, \u0438 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, \u0435\u0441\u043b\u0438 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439. \u041f\u043e\u0447\u0442\u0438 \u0432\u0441\u0435\u0433\u0434\u0430 \u0441\u0442\u043e\u0438\u0442 \u043f\u0435\u0440\u0435\u0434 idiv: \u0434\u0435\u043b\u0438\u043c\u043e\u0435 \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0438\u0437 \u043f\u0430\u0440\u044b EDX:EAX.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "EDX = \u0437\u043d\u0430\u043a EAX (\u043f\u0435\u0440\u0435\u0434 idiv)", "10.5");
		rec("cdqe", "convert doubleword to quadword (extended)", "\u0441\u0438-\u0434\u0438-\u043a\u044c\u044e-\u0438", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0434\u0432\u043e\u0439\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0434\u043e \u0447\u0435\u0442\u0432\u0435\u0440\u043d\u043e\u0433\u043e", "\u0420\u0430\u0441\u0448\u0438\u0440\u044f\u0435\u0442 EAX \u0434\u043e RAX \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c. \u0422\u043e \u0436\u0435, \u0447\u0442\u043e movsxd rax, eax, \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u0440\u043e\u0447\u0435.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "EAX \u2192 RAX \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "10.2,20.4");
		rec("clc", "clear carry flag", "\u043a\u043b\u0438\u0430 \u043a\u044d\u0440\u0438 \u0444\u043b\u044d\u0433", "\u0441\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0444\u043b\u0430\u0433 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430", "\u0421\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u0444\u043b\u0430\u0433 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430: CF = 0.", "CF = 0", "CF = 0", "9.6");
		rec("cld", "clear direction flag", "\u043a\u043b\u0438\u0430 \u0434\u0438\u0440\u044d\u043a\u0448\u043d \u0444\u043b\u044d\u0433", "\u0441\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0444\u043b\u0430\u0433 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f", "\u0421\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u0444\u043b\u0430\u0433 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f DF: \u0441\u0442\u0440\u043e\u043a\u043e\u0432\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 (movsb, stosb \u0438 \u0434\u0440\u0443\u0433\u0438\u0435) \u043f\u043e\u0439\u0434\u0443\u0442 \u043f\u043e \u043f\u0430\u043c\u044f\u0442\u0438 \u0432\u043f\u0435\u0440\u0451\u0434. \u0422\u0430\u043a \u043f\u043e\u0447\u0442\u0438 \u0432\u0441\u0435\u0433\u0434\u0430 \u0438 \u0435\u0441\u0442\u044c.", "DF = 0", "DF = 0: \u0441\u0442\u0440\u043e\u043a\u0438 \u0438\u0434\u0443\u0442 \u0432\u043f\u0435\u0440\u0451\u0434", "9.6");
		rec("clflush", "cache line flush", "\u043a\u044d\u0448 \u043b\u0430\u0439\u043d \u0444\u043b\u0430\u0448", "\u0441\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443 \u043a\u044d\u0448\u0430", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c \u0438 \u0432\u044b\u043a\u0438\u0434\u044b\u0432\u0430\u0435\u0442 \u0438\u0437 \u043a\u044d\u0448\u0430 \u0441\u0442\u0440\u043e\u043a\u0443 (\u043e\u0431\u044b\u0447\u043d\u043e 64 \u0431\u0430\u0439\u0442\u0430), \u0433\u0434\u0435 \u043b\u0435\u0436\u0438\u0442 \u0430\u0434\u0440\u0435\u0441.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u044b\u043a\u0438\u043d\u0443\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443 \u043a\u044d\u0448\u0430 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c", "");
		rec("cli", "clear interrupt flag", "\u043a\u043b\u0438\u0430 \u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442 \u0444\u043b\u044d\u0433", "\u0441\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0444\u043b\u0430\u0433 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0439", "\u0417\u0430\u043f\u0440\u0435\u0449\u0430\u0435\u0442 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u043d\u044b\u0435 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f (\u0444\u043b\u0430\u0433 IF = 0). \u0422\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u044f\u0434\u0440\u0430 (34.8).", "IF = 0", "\u0437\u0430\u043f\u0440\u0435\u0442\u0438\u0442\u044c \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f (\u044f\u0434\u0440\u043e)", "34.8");
		rec("cmc", "complement carry flag", "\u043a\u043e\u043c\u043f\u043b\u0438\u043c\u044d\u043d\u0442 \u043a\u044d\u0440\u0438 \u0444\u043b\u044d\u0433", "\u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0444\u043b\u0430\u0433 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430", "\u041f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0444\u043b\u0430\u0433 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430 CF.", "CF \u043f\u0435\u0440\u0435\u0432\u0451\u0440\u043d\u0443\u0442", "CF \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u044c", "9.6");
		rec("cmova", "conditional move if above", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0 \u0438 ZF = 0); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovnbe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovae", "conditional move if above or equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2265 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovnb, cmovnc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2265 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovb", "conditional move if below", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovc, cmovnae.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovbe", "conditional move if below or equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2264 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1 \u0438\u043b\u0438 ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovna.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2264 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovc", "conditional move if carry", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441, CF = 1", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovb, cmovnae.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441, CF = 1", "20.10,9.8");
		rec("cmove", "conditional move if equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u043e\u043b\u044c (ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovz.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e", "20.10,9.8");
		rec("cmovg", "conditional move if greater", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 0 \u0438 SF = OF); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovnle.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "20.10,9.8");
		rec("cmovge", "conditional move if greater or equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2265 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF = OF); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovnl.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2265 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "20.10,9.8");
		rec("cmovl", "conditional move if less", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF \u2260 OF); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovnge.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "20.10,9.8");
		rec("cmovle", "conditional move if less or equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2264 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 1 \u0438\u043b\u0438 SF \u2260 OF); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovng.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u2264 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "20.10,9.8");
		rec("cmovna", "conditional move if not above", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1 \u0438\u043b\u0438 ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovbe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovnae", "conditional move if not above or equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovb, cmovc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovnb", "conditional move if not below", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovae, cmovnc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovnbe", "conditional move if not below or equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0 \u0438 ZF = 0); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmova.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "20.10,9.8");
		rec("cmovnc", "conditional move if not carry", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, CF = 0", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovae, cmovnb.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, CF = 0", "20.10,9.8");
		rec("cmovne", "conditional move if not equal", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u0435 \u043d\u043e\u043b\u044c (ZF = 0); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmovnz.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e", "20.10,9.8");
