		rec("cmovs", "conditional move if sign", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 (SF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435", "20.10,9.6");
		rec("cmovz", "conditional move if zero", "", "\u0441\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u043e\u043b\u044c", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u043e\u043b\u044c (ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e\u0435 if \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 (20.10). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: cmove.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u043e\u043b\u044c", "20.10,9.8");
		rec("cmp", "compare", "\u043a\u044d\u043c\u043f\u0435\u0440", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c", "\u0412\u044b\u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u0442\u043e\u0440\u043e\u0435 \u0438\u0437 \u043f\u0435\u0440\u0432\u043e\u0433\u043e, \u043d\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0438\u043a\u0443\u0434\u0430 \u043d\u0435 \u043f\u0438\u0448\u0435\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0444\u043b\u0430\u0433\u0438. \u0421\u0440\u0430\u0437\u0443 \u0437\u0430 \u043d\u0438\u043c \u043f\u043e\u0447\u0442\u0438 \u0432\u0441\u0435\u0433\u0434\u0430 \u0441\u0442\u043e\u0438\u0442 \u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434 (9.7).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a sub", "\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435: \u0432\u044b\u0447\u0438\u0442\u0430\u0435\u0442, \u043f\u0438\u0448\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0444\u043b\u0430\u0433\u0438", "9.7");
		rec("cmps", "compare strings", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u0442\u0440\u0438\u043d\u0433\u0437", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0438", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 [RSI] \u0438 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. repe cmpsb \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u043a\u0443\u0441\u043a\u043e\u0432 \u043f\u0430\u043c\u044f\u0442\u0438 (memcmp).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 [RSI] \u0438 [RDI]", "");
		rec("cmpsb", "compare strings", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u0442\u0440\u0438\u043d\u0433\u0437", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0438", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 1 \u0431\u0430\u0439\u0442 \u0432 [RSI] \u0438 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. repe cmpsb \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u043a\u0443\u0441\u043a\u043e\u0432 \u043f\u0430\u043c\u044f\u0442\u0438 (memcmp).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 1 \u0431\u0430\u0439\u0442 \u0432 [RSI] \u0438 [RDI]", "");
		rec("cmpsd.sse", "compare scalar double", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0447\u0438\u0441\u043b\u0430 double", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u043f\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044e \u0438\u0437 \u0442\u0440\u0435\u0442\u044c\u0435\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430 \u0438 \u043f\u0438\u0448\u0435\u0442 \u0432 xmm \u043c\u0430\u0441\u043a\u0443: \u0432\u0441\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u044b (\u0434\u0430) \u0438\u043b\u0438 \u0432\u0441\u0435 \u043d\u0443\u043b\u0438 (\u043d\u0435\u0442).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 double, \u043f\u0438\u0448\u0435\u0442 \u043c\u0430\u0441\u043a\u0443", "");
		rec("cmpsd.str", "compare string doubleword", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u0442\u0440\u0438\u043d\u0433 \u0434\u0430\u0431\u043b\u0443\u043e\u0440\u0434", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0438 \u043f\u043e 4 \u0431\u0430\u0439\u0442\u0430", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 4 \u0431\u0430\u0439\u0442\u0430 \u0432 [RSI] \u0438 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f.", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 4 \u0431\u0430\u0439\u0442\u0430 [RSI] \u0438 [RDI]", "");
		rec("cmpsq", "compare strings", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u0442\u0440\u0438\u043d\u0433\u0437", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0438", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 8 \u0431\u0430\u0439\u0442 \u0432 [RSI] \u0438 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. repe cmpsb \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u043a\u0443\u0441\u043a\u043e\u0432 \u043f\u0430\u043c\u044f\u0442\u0438 (memcmp).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 8 \u0431\u0430\u0439\u0442 \u0432 [RSI] \u0438 [RDI]", "");
		rec("cmpsw", "compare strings", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u0442\u0440\u0438\u043d\u0433\u0437", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0438", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 2 \u0431\u0430\u0439\u0442\u0430 \u0432 [RSI] \u0438 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. repe cmpsb \u2014 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0432\u0443\u0445 \u043a\u0443\u0441\u043a\u043e\u0432 \u043f\u0430\u043c\u044f\u0442\u0438 (memcmp).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 2 \u0431\u0430\u0439\u0442\u0430 \u0432 [RSI] \u0438 [RDI]", "");
		rec("cmpxchg", "compare and exchange", "\u043a\u044d\u043c\u043f\u0435\u0440 \u044d\u043d\u0434 \u0438\u043a\u0441\u0447\u0435\u0439\u043d\u0434\u0436", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0438 \u043e\u0431\u043c\u0435\u043d\u044f\u0442\u044c", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 RAX (EAX) \u0441 \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u043e\u043c \u0432 \u043f\u0430\u043c\u044f\u0442\u0438. \u0420\u0430\u0432\u043d\u044b \u2014 \u043f\u0438\u0448\u0435\u0442 \u0442\u0443\u0434\u0430 \u043d\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 ZF = 1. \u041d\u0435 \u0440\u0430\u0432\u043d\u044b \u2014 \u043a\u043b\u0430\u0434\u0451\u0442 \u0442\u0435\u043a\u0443\u0449\u0435\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0432 RAX \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 ZF = 0. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c lock \u2014 \u043e\u0441\u043d\u043e\u0432\u0430 \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043e\u043a (\u041f3.5).", "ZF = 1, \u0435\u0441\u043b\u0438 \u043e\u0431\u043c\u0435\u043d \u0441\u043b\u0443\u0447\u0438\u043b\u0441\u044f; \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043a\u0430\u043a \u0443 cmp", "\u0435\u0441\u043b\u0438 [mem] == RAX: [mem] = \u043d\u043e\u0432\u043e\u0435", "\u041f3.5");
		rec("cmpxchg16b", "compare and exchange 16 bytes", "\u043a\u044d\u043c\u043f\u0435\u0440 \u044d\u043d\u0434 \u0438\u043a\u0441\u0447\u0435\u0439\u043d\u0434\u0436 \u0441\u0438\u043a\u0441\u0442\u0438\u043d \u0431\u0430\u0439\u0442\u0441", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0438 \u043e\u0431\u043c\u0435\u043d\u044f\u0442\u044c 16 \u0431\u0430\u0439\u0442", "\u0422\u043e \u0436\u0435, \u0447\u0442\u043e cmpxchg, \u043d\u043e \u0434\u043b\u044f 8 \u0438\u043b\u0438 16 \u0431\u0430\u0439\u0442 \u0441\u0440\u0430\u0437\u0443: \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0441 \u043f\u0430\u0440\u043e\u0439 EDX:EAX (RDX:RAX), \u043d\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0435\u0440\u0451\u0442 \u0438\u0437 ECX:EBX (RCX:RBX).", "ZF = 1, \u0435\u0441\u043b\u0438 \u043e\u0431\u043c\u0435\u043d \u0441\u043b\u0443\u0447\u0438\u043b\u0441\u044f", "cmpxchg \u0434\u043b\u044f 8 \u0438\u043b\u0438 16 \u0431\u0430\u0439\u0442", "\u041f3.5");
		rec("cmpxchg8b", "compare and exchange 8 bytes", "\u043a\u044d\u043c\u043f\u0435\u0440 \u044d\u043d\u0434 \u0438\u043a\u0441\u0447\u0435\u0439\u043d\u0434\u0436 \u044d\u0439\u0442 \u0431\u0430\u0439\u0442\u0441", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0438 \u043e\u0431\u043c\u0435\u043d\u044f\u0442\u044c 8 \u0431\u0430\u0439\u0442", "\u0422\u043e \u0436\u0435, \u0447\u0442\u043e cmpxchg, \u043d\u043e \u0434\u043b\u044f 8 \u0438\u043b\u0438 16 \u0431\u0430\u0439\u0442 \u0441\u0440\u0430\u0437\u0443: \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0441 \u043f\u0430\u0440\u043e\u0439 EDX:EAX (RDX:RAX), \u043d\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0431\u0435\u0440\u0451\u0442 \u0438\u0437 ECX:EBX (RCX:RBX).", "ZF = 1, \u0435\u0441\u043b\u0438 \u043e\u0431\u043c\u0435\u043d \u0441\u043b\u0443\u0447\u0438\u043b\u0441\u044f", "cmpxchg \u0434\u043b\u044f 8 \u0438\u043b\u0438 16 \u0431\u0430\u0439\u0442", "\u041f3.5");
		rec("comisd", "compare scalar ordered double", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u043e\u0440\u0434\u044d\u0434 \u0434\u0430\u0431\u043b", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0434\u0432\u0430 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u043b\u0430 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u043f\u0440\u0438 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u043c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0438: \u0434\u0430\u043b\u044c\u0448\u0435 \u0438\u0434\u0443\u0442 ja, jb, jae, jbe. PF = 1 \u0437\u043d\u0430\u0447\u0438\u0442 \u00ab\u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b \u2014 NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e)\u00bb, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u044f\u0434\u043e\u043c \u0447\u0430\u0441\u0442\u043e \u0441\u0442\u043e\u0438\u0442 jp.", "ZF, PF, CF \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e; OF = SF = 0", "\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445: \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u0443 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445", "9.8");
		rec("comiss", "compare scalar ordered single", "\u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u043e\u0440\u0434\u044d\u0434 \u0441\u0438\u043d\u0433\u043b", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0434\u0432\u0430 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u043b\u0430 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u043f\u0440\u0438 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u043c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0438: \u0434\u0430\u043b\u044c\u0448\u0435 \u0438\u0434\u0443\u0442 ja, jb, jae, jbe. PF = 1 \u0437\u043d\u0430\u0447\u0438\u0442 \u00ab\u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b \u2014 NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e)\u00bb, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u044f\u0434\u043e\u043c \u0447\u0430\u0441\u0442\u043e \u0441\u0442\u043e\u0438\u0442 jp.", "ZF, PF, CF \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e; OF = SF = 0", "\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445: \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u0443 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445", "9.8");
		rec("cpuid", "CPU identification", "\u0441\u0438-\u043f\u0438-\u044e \u0430\u0439\u0434\u044d\u043d\u0442\u0438\u0444\u0438\u043a\u0435\u0439\u0448\u043d", "\u043e\u043f\u043e\u0437\u043d\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430", "\u0421\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440 \u043e \u043d\u0451\u043c \u0441\u0430\u043c\u043e\u043c: \u043d\u043e\u043c\u0435\u0440 \u0432\u043e\u043f\u0440\u043e\u0441\u0430 \u2014 \u0432 EAX (\u0438\u043d\u043e\u0433\u0434\u0430 \u0435\u0449\u0451 ECX), \u043e\u0442\u0432\u0435\u0442 \u2014 \u0432 EAX, EBX, ECX, EDX. \u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u043e\u043f\u0440\u043e\u0441 0 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0438\u043c\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f: GenuineIntel \u0438\u043b\u0438 AuthenticAMD.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0441\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440 \u043e \u043d\u0451\u043c \u0441\u0430\u043c\u043e\u043c", "33.5,\u041f2.8");
		rec("cqo", "convert quadword to octoword", "\u0441\u0438-\u043a\u044c\u044e-\u043e\u0443", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0447\u0435\u0442\u0432\u0435\u0440\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e \u0434\u043e \u0432\u043e\u0441\u044c\u043c\u0435\u0440\u043d\u043e\u0433\u043e", "\u0417\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 RDX \u0437\u043d\u0430\u043a\u043e\u043c RAX. \u0413\u043e\u0442\u043e\u0432\u0438\u0442 \u043f\u0430\u0440\u0443 RDX:RAX \u043f\u0435\u0440\u0435\u0434 64-\u0431\u0438\u0442\u043d\u044b\u043c idiv.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "RDX = \u0437\u043d\u0430\u043a RAX (\u043f\u0435\u0440\u0435\u0434 idiv)", "10.5");
		rec("crc32", "accumulate CRC32 value", "\u044d\u043a\u044c\u044e\u043c\u044c\u044e\u043b\u0435\u0439\u0442 \u0441\u0438-\u0430\u0440-\u0441\u0438", "\u043d\u0430\u043a\u043e\u043f\u0438\u0442\u044c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u0443\u044e \u0441\u0443\u043c\u043c\u0443 CRC32", "\u0428\u0430\u0433 \u043f\u043e\u0434\u0441\u0447\u0451\u0442\u0430 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u043e\u0439 \u0441\u0443\u043c\u043c\u044b CRC32C, \u0441\u0434\u0435\u043b\u0430\u043d\u043d\u044b\u0439 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u043e\u043c. \u0423\u0432\u0438\u0434\u0435\u043b \u0432 \u0446\u0438\u043a\u043b\u0435 \u043f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0446\u0435\u043b\u043e\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u0445\u0435\u0448.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0448\u0430\u0433 \u043f\u043e\u0434\u0441\u0447\u0451\u0442\u0430 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u043e\u0439 \u0441\u0443\u043c\u043c\u044b CRC32C", "");
		rec("cvtsd2si", "convert scalar double to signed integer", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b \u0442\u0443 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0432 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c (\u043e\u0431\u044b\u0447\u043d\u043e \u0434\u043e \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0433\u043e \u0446\u0435\u043b\u043e\u0433\u043e).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u2192 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c", "12.2");
		rec("cvtsd2ss", "convert scalar double to scalar single", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b \u0442\u0443 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 double \u0432 float", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442) \u0432 float (4 \u0431\u0430\u0439\u0442\u0430).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "double \u2192 float", "12.2");
		rec("cvtsi2sd", "convert signed integer to scalar double", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440 \u0442\u0443 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0446\u0435\u043b\u043e\u0435 \u0432 \u0434\u0440\u043e\u0431\u043d\u043e\u0435", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0446\u0435\u043b\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0434\u0440\u043e\u0431\u043d\u043e\u0435: double (sd) \u0438\u043b\u0438 float (ss).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0446\u0435\u043b\u043e\u0435 \u2192 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 (double/float)", "12.2");
		rec("cvtsi2ss", "convert signed integer to scalar single", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440 \u0442\u0443 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0446\u0435\u043b\u043e\u0435 \u0432 \u0434\u0440\u043e\u0431\u043d\u043e\u0435", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0446\u0435\u043b\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0434\u0440\u043e\u0431\u043d\u043e\u0435: double (sd) \u0438\u043b\u0438 float (ss).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0446\u0435\u043b\u043e\u0435 \u2192 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 (double/float)", "12.2");
		rec("cvtss2sd", "convert scalar single to scalar double", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b \u0442\u0443 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 float \u0432 double", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430) \u0432 double (8 \u0431\u0430\u0439\u0442). \u0422\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0433\u043e\u0442\u043e\u0432\u0438\u0442 float \u0434\u043b\u044f printf.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "float \u2192 double", "12.2");
		rec("cvtss2si", "convert scalar single to signed integer", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b \u0442\u0443 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0432 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c (\u043e\u0431\u044b\u0447\u043d\u043e \u0434\u043e \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0433\u043e \u0446\u0435\u043b\u043e\u0433\u043e).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u2192 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c", "12.2");
		rec("cvttsd2si", "convert with truncation scalar double to signed integer", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0443\u0438\u0437 \u0442\u0440\u0430\u043d\u043a\u0435\u0439\u0448\u043d \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b \u0442\u0443 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0432 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u043d\u0438\u0435\u043c", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0446\u0435\u043b\u043e\u0435, \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u044f \u0434\u0440\u043e\u0431\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u2014 \u043a\u0430\u043a (int)x \u0432 C.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u2192 \u0446\u0435\u043b\u043e\u0435, \u0434\u0440\u043e\u0431\u044c \u043e\u0442\u0431\u0440\u043e\u0441\u0438\u0442\u044c", "12.2");
		rec("cvttss2si", "convert with truncation scalar single to signed integer", "\u043a\u043e\u043d\u0432\u0451\u0440\u0442 \u0443\u0438\u0437 \u0442\u0440\u0430\u043d\u043a\u0435\u0439\u0448\u043d \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b \u0442\u0443 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440", "\u043f\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0432 \u0446\u0435\u043b\u043e\u0435 \u0441 \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u043d\u0438\u0435\u043c", "\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u0442 \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0446\u0435\u043b\u043e\u0435, \u043e\u0442\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u044f \u0434\u0440\u043e\u0431\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u2014 \u043a\u0430\u043a (int)x \u0432 C.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u2192 \u0446\u0435\u043b\u043e\u0435, \u0434\u0440\u043e\u0431\u044c \u043e\u0442\u0431\u0440\u043e\u0441\u0438\u0442\u044c", "12.2");
		rec("cwd", "convert word to doubleword", "\u0441\u0438-\u0434\u0430\u0431\u043b-\u044e-\u0434\u0438", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0441\u043b\u043e\u0432\u043e \u0434\u043e \u0434\u0432\u043e\u0439\u043d\u043e\u0433\u043e \u0441\u043b\u043e\u0432\u0430", "\u0417\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 DX \u0437\u043d\u0430\u043a\u043e\u043c AX, \u0433\u043e\u0442\u043e\u0432\u0438\u0442 \u0434\u0435\u043b\u0435\u043d\u0438\u0435 2-\u0431\u0430\u0439\u0442\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b. \u0412\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0440\u0435\u0434\u043a\u043e.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "DX = \u0437\u043d\u0430\u043a AX", "10.5");
		rec("cwde", "convert word to doubleword (extended)", "\u0441\u0438-\u0434\u0430\u0431\u043b-\u044e-\u0434\u0438-\u0438", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0441\u043b\u043e\u0432\u043e \u0434\u043e \u0434\u0432\u043e\u0439\u043d\u043e\u0433\u043e \u0441\u043b\u043e\u0432\u0430", "\u0420\u0430\u0441\u0448\u0438\u0440\u044f\u0435\u0442 AX \u0434\u043e EAX \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c. \u041c\u043b\u0430\u0434\u0448\u0430\u044f \u0441\u0435\u0441\u0442\u0440\u0430 cdqe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "AX \u2192 EAX \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "20.4");
		rec("dec", "decrement", "\u0434\u044d\u043a\u0440\u0438\u043c\u044d\u043d\u0442", "\u0443\u043c\u0435\u043d\u044c\u0448\u0438\u0442\u044c", "\u0412\u044b\u0447\u0438\u0442\u0430\u0435\u0442 \u0435\u0434\u0438\u043d\u0438\u0446\u0443: a = a \u2212 1.", "\u043c\u0435\u043d\u044f\u0435\u0442 ZF, SF, OF; CF \u043d\u0435 \u0442\u0440\u043e\u0433\u0430\u0435\u0442", "a = a \u2212 1", "10.5");
		rec("div", "divide", "\u0434\u0438\u0432\u0430\u0439\u0434", "\u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u044c (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0411\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u0434\u0435\u043b\u0438\u043c\u043e\u0435 \u2014 \u043f\u0430\u0440\u0430 RDX:RAX (\u0438\u043b\u0438 EDX:EAX), \u0447\u0430\u0441\u0442\u043d\u043e\u0435 \u2192 RAX, \u043e\u0441\u0442\u0430\u0442\u043e\u043a \u2192 RDX. \u0414\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u043d\u043e\u043b\u044c \u0440\u043e\u043d\u044f\u0435\u0442 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443 (\u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 #DE, 34.2).", "\u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u044b", "RAX = \u0447\u0430\u0441\u0442\u043d\u043e\u0435, RDX = \u043e\u0441\u0442\u0430\u0442\u043e\u043a", "10.5,18.8");
		rec("divpd", "divide packed double", "\u0434\u0438\u0432\u0430\u0439\u0434 \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "\u0414\u0435\u043b\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("divps", "divide packed single", "\u0434\u0438\u0432\u0430\u0439\u0434 \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "\u0414\u0435\u043b\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("divsd", "divide scalar double", "\u0434\u0438\u0432\u0430\u0439\u0434 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u0414\u0435\u043b\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "12.2");
		rec("divss", "divide scalar single", "\u0434\u0438\u0432\u0430\u0439\u0434 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u0414\u0435\u043b\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "12.2");
		rec("endbr64", "end branch 64", "\u044d\u043d\u0434 \u0431\u0440\u044d\u043d\u0447 \u0441\u0438\u043a\u0441\u0442\u0438 \u0444\u043e", "\u043a\u043e\u043d\u0435\u0446 \u0432\u0435\u0442\u0432\u043b\u0435\u043d\u0438\u044f", "\u041c\u0435\u0442\u043a\u0430 \u00ab\u0441\u044e\u0434\u0430 \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u044b\u0433\u0430\u0442\u044c\u00bb \u0434\u043b\u044f \u0437\u0430\u0449\u0438\u0442\u044b CET (Control-flow Enforcement Technology). \u0421\u0430\u043c\u0430 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0412 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430\u0445 Windows \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0440\u0435\u0434\u043a\u043e.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u0435\u0442\u043a\u0430 \u0434\u043b\u044f \u0437\u0430\u0449\u0438\u0442\u044b CET, \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442", "");
		rec("enter", "enter", "\u044d\u043d\u0442\u044d\u0440", "\u0432\u043e\u0439\u0442\u0438", "\u0421\u0442\u0440\u043e\u0438\u0442 \u043a\u0430\u0434\u0440 \u0441\u0442\u0435\u043a\u0430, \u043a\u0430\u043a push rbp; mov rbp, rsp; sub rsp, N. \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440\u044b \u0435\u0451 \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0441\u0442\u0440\u043e\u0438\u0442 \u043a\u0430\u0434\u0440 \u0441\u0442\u0435\u043a\u0430 (\u0440\u0435\u0434\u043a\u043e\u0441\u0442\u044c)", "11.3");
		rec("fadd", "x87 floating-point operation", "\u044d\u043a\u0441-\u0432\u043e\u0441\u0435\u043c\u044c\u0434\u0435\u0441\u044f\u0442-\u0441\u0435\u043c\u044c", "\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u044f \u0431\u043b\u043e\u043a\u0430 x87", "\u041e\u043f\u0435\u0440\u0430\u0446\u0438\u044f \u0441\u0442\u0430\u0440\u043e\u0433\u043e \u0431\u043b\u043e\u043a\u0430 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 x87 (\u0447\u0438\u0441\u043b\u0430 \u043d\u0430 \u0435\u0433\u043e \u0441\u0442\u0435\u043a\u0435 ST0\u2013ST7). \u0412 64-\u0431\u0438\u0442\u043d\u044b\u0445 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430\u0445 Windows \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f.", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0444\u043b\u0430\u0433\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0443 fcomi \u0438 fucomi", "x87: \u0441\u0442\u0430\u0440\u044b\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f", "");
		rec("fld", "floating-point load", "\u0444\u043b\u043e\u0443\u0442\u0438\u043d\u0433-\u043f\u043e\u0439\u043d\u0442 \u043b\u043e\u0443\u0434", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u043d\u0430 \u0441\u0442\u0435\u043a x87", "\u0421\u0442\u0430\u0440\u044b\u0439 \u0431\u043b\u043e\u043a \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 x87: \u043a\u043b\u0430\u0434\u0451\u0442 \u0447\u0438\u0441\u043b\u043e \u043d\u0430 \u0435\u0433\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u0442\u0435\u043a \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u0432 ST0\u2013ST7. \u0412 64-\u0431\u0438\u0442\u043d\u044b\u0445 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430\u0445 Windows \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "x87: \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0447\u0438\u0441\u043b\u043e \u043d\u0430 \u0441\u0432\u043e\u0439 \u0441\u0442\u0435\u043a", "");
		rec("fstp", "floating-point store (and pop)", "\u0444\u043b\u043e\u0443\u0442\u0438\u043d\u0433-\u043f\u043e\u0439\u043d\u0442 \u0441\u0442\u043e\u0440 \u044d\u043d\u0434 \u043f\u043e\u043f", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c (\u0438 \u0441\u043d\u044f\u0442\u044c \u0441\u043e \u0441\u0442\u0435\u043a\u0430 x87)", "\u0421\u0442\u0430\u0440\u044b\u0439 \u0431\u043b\u043e\u043a x87: \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0447\u0438\u0441\u043b\u043e \u0438\u0437 ST0 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c; \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0441 p \u0435\u0449\u0451 \u0438 \u0441\u043d\u0438\u043c\u0430\u0435\u0442 \u0435\u0433\u043e \u0441\u043e \u0441\u0442\u0435\u043a\u0430 x87.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "x87: \u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0447\u0438\u0441\u043b\u043e \u0438\u0437 ST0", "");
		rec("hlt", "halt", "\u0445\u043e\u043b\u0442", "\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c\u0441\u044f", "\u041e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440 \u0434\u043e \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f. \u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0430 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043a\u043e\u043b\u044c\u0446\u0435 0 (27.4).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440 (\u043a\u043e\u043b\u044c\u0446\u043e 0)", "27.4");
		rec("idiv", "integer divide", "\u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440 \u0434\u0438\u0432\u0430\u0439\u0434", "\u0440\u0430\u0437\u0434\u0435\u043b\u0438\u0442\u044c \u0446\u0435\u043b\u044b\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0417\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0434\u0435\u043b\u0435\u043d\u0438\u0435: \u0434\u0435\u043b\u0438\u043c\u043e\u0435 \u2014 \u043f\u0430\u0440\u0430 RDX:RAX, \u0447\u0430\u0441\u0442\u043d\u043e\u0435 \u2192 RAX, \u043e\u0441\u0442\u0430\u0442\u043e\u043a \u2192 RDX. \u041f\u0435\u0440\u0435\u0434 \u043d\u0438\u043c \u043e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 cdq \u0438\u043b\u0438 cqo.", "\u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u044b", "\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c: RAX, RDX", "10.5");
		rec("imul", "integer multiply", "\u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440 \u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0430\u0439", "\u0443\u043c\u043d\u043e\u0436\u0438\u0442\u044c \u0446\u0435\u043b\u044b\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0417\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435. \u0421 \u0434\u0432\u0443\u043c\u044f \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430\u043c\u0438: imul a, b \u2014 \u044d\u0442\u043e a = a * b. \u0421 \u0442\u0440\u0435\u043c\u044f: imul a, b, 10 \u2014 \u044d\u0442\u043e a = b * 10.", "CF \u0438 OF = 1, \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435 \u043f\u043e\u043c\u0435\u0441\u0442\u0438\u043b\u0441\u044f; ZF \u0438 SF \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u044b", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "10.5");
		rec("inc", "increment", "\u0438\u043d\u043a\u0440\u0438\u043c\u044d\u043d\u0442", "\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c", "\u041f\u0440\u0438\u0431\u0430\u0432\u043b\u044f\u0435\u0442 \u0435\u0434\u0438\u043d\u0438\u0446\u0443: a = a + 1.", "\u043c\u0435\u043d\u044f\u0435\u0442 ZF, SF, OF; CF \u043d\u0435 \u0442\u0440\u043e\u0433\u0430\u0435\u0442", "a = a + 1", "10.5");
		rec("int", "interrupt", "\u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442", "\u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0435", "\u0412\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0435 \u0441 \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u043c \u043d\u043e\u043c\u0435\u0440\u043e\u043c (34.1). \u0412 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430\u0445 Windows x64 \u043f\u043e\u0447\u0442\u0438 \u0432\u0441\u0435\u0433\u0434\u0430 \u044d\u0442\u043e int 29h \u2014 __fastfail: \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u0441\u0430\u043c\u0430 \u0430\u0432\u0430\u0440\u0438\u0439\u043d\u043e \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044f, \u0437\u0430\u043c\u0435\u0442\u0438\u0432 \u043f\u043e\u0440\u0447\u0443 \u0434\u0430\u043d\u043d\u044b\u0445 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0441\u0440\u0430\u0431\u043e\u0442\u0430\u043b\u0430 \u043a\u0430\u043d\u0430\u0440\u0435\u0439\u043a\u0430, 11.9).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0435 \u0441 \u043d\u043e\u043c\u0435\u0440\u043e\u043c; int 29h \u2014 fastfail", "34.1");
		rec("int3", "interrupt 3", "\u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442 \u0441\u0440\u0438", "\u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0435 3", "\u0422\u043e\u0447\u043a\u0430 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0430: \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440 \u043e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443 \u0438 \u0437\u043e\u0432\u0451\u0442 \u043e\u0442\u043b\u0430\u0434\u0447\u0438\u043a (13.1). \u042d\u0442\u043e \u0431\u0430\u0439\u0442 CC. MSVC \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u0438\u043c \u043f\u0443\u0441\u0442\u043e\u0442\u044b \u043c\u0435\u0436\u0434\u0443 \u0444\u0443\u043d\u043a\u0446\u0438\u044f\u043c\u0438.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0442\u043e\u0447\u043a\u0430 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0430 (\u0431\u0430\u0439\u0442 CC)", "13.1");
		rec("invlpg", "invalidate TLB entry for page", "\u0438\u043d\u0432\u044d\u043b\u0438\u0434\u0435\u0439\u0442 \u0442\u0438-\u044d\u043b-\u0431\u0438 \u044d\u043d\u0442\u0440\u0438 \u0444\u043e \u043f\u044d\u0439\u0434\u0436", "\u0441\u0431\u0440\u043e\u0441\u0438\u0442\u044c \u0437\u0430\u043f\u0438\u0441\u044c TLB \u0434\u043b\u044f \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b", "\u0421\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u0437\u0430\u043f\u043e\u043c\u043d\u0435\u043d\u043d\u044b\u0439 \u0432 TLB \u043f\u0435\u0440\u0435\u0432\u043e\u0434 \u0430\u0434\u0440\u0435\u0441\u0430 \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b (32.12). \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0437\u0430\u0431\u044b\u0442\u044c \u043f\u0435\u0440\u0435\u0432\u043e\u0434 \u0430\u0434\u0440\u0435\u0441\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b (TLB)", "32.12");
		rec("iretq", "interrupt return", "\u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442 \u0440\u0438\u0442\u0451\u0440\u043d", "\u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f", "\u0412\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u0430 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f: \u0441\u043d\u0438\u043c\u0430\u0435\u0442 \u0441\u043e \u0441\u0442\u0435\u043a\u0430 RIP, CS, RFLAGS, RSP \u0438 SS (34.6).", "\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u0441\u043e \u0441\u0442\u0435\u043a\u0430", "\u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a\u0430 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f", "34.6");
		rec("ja", "jump if above", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0 \u0438 ZF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jnbe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
		rec("jae", "jump if above or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u2265 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jnb, jnc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u2265 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
		rec("jb", "jump if below", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jc, jnae.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
		rec("jbe", "jump if below or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u2264 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1 \u0438\u043b\u0438 ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jna.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u2264 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
		rec("jc", "jump if carry", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441, CF = 1", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jb, jnae.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441, CF = 1", "9.8");
		rec("je", "jump if equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u043e\u043b\u044c (ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jz.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e", "9.8");
		rec("jecxz", "jump if ECX is zero", "\u0434\u0436\u0430\u043c\u043f \u0438\u0444 \u0438-\u0441\u0438-\u044d\u043a\u0441 \u0438\u0437 \u0437\u0438\u0440\u043e\u0443", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 ECX = 0", "\u041f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 ECX \u0440\u0430\u0432\u0435\u043d \u043d\u0443\u043b\u044e. \u0424\u043b\u0430\u0433\u0438 \u043d\u0435 \u0441\u043c\u043e\u0442\u0440\u0438\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 ECX = 0", "9.8");
		rec("jg", "jump if greater", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 0 \u0438 SF = OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jnle.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jge", "jump if greater or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u2265 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF = OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jnl.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u2265 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jl", "jump if less", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF \u2260 OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jnge.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jle", "jump if less or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u2264 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 1 \u0438\u043b\u0438 SF \u2260 OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jng.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u2264 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jmp", "jump", "\u0434\u0436\u0430\u043c\u043f", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c", "\u0411\u0435\u0437\u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u0434\u0430\u043b\u044c\u0448\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u043a\u043e\u0434 \u043f\u043e \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443. \u041f\u0440\u044b\u0436\u043e\u043a \u043d\u0430\u0437\u0430\u0434 \u2014 \u043f\u0440\u0438\u0437\u043d\u0430\u043a \u0446\u0438\u043a\u043b\u0430 (10.9). jmp qword ptr [...] \u2014 \u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 (switch, 20.4).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u0435\u0437\u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434", "10.9");
		rec("jna", "jump if not above", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1 \u0438\u043b\u0438 ZF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jbe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
		rec("jnae", "jump if not above or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jb, jc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
