		rec("jnbe", "jump if not below or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0 \u0438 ZF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: ja.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "9.8");
		rec("jnc", "jump if not carry", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, CF = 0", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jae, jnb.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, CF = 0", "9.8");
		rec("jne", "jump if not equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u0435 \u043d\u043e\u043b\u044c (ZF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jnz.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e", "9.8");
		rec("jng", "jump if not greater", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 1 \u0438\u043b\u0438 SF \u2260 OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jle.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jnge", "jump if not greater or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF \u2260 OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jl.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jnl", "jump if not less", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF = OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jge.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jnle", "jump if not less or equal", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 0 \u0438 SF = OF); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jg.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "9.8");
		rec("jno", "jump if not overflow", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0431\u044b\u043b\u043e \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430 (OF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 OF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f", "9.6,9.8");
		rec("jnp", "jump if not parity", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 PF = 0", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0444\u043b\u0430\u0433 \u0447\u0451\u0442\u043d\u043e\u0441\u0442\u0438 PF = 0 (PF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jpo.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 PF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 PF = 0", "9.6,9.8");
		rec("jns", "jump if not sign", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 (SF = 0); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435", "9.6,9.8");
