		rec("jp", "jump if parity", "", "\u043f\u0440\u044b\u0433\u043d\u0443\u0442\u044c, \u0435\u0441\u043b\u0438 PF = 1 (\u0447\u0430\u0441\u0442\u043e: NaN)", "\u0423\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u043e\u0434: \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 \u0444\u043b\u0430\u0433 \u0447\u0451\u0442\u043d\u043e\u0441\u0442\u0438 PF = 1, \u0430 \u043f\u043e\u0441\u043b\u0435 ucomisd \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e) (PF = 1); \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0438\u0434\u0451\u0442 \u0434\u0430\u043b\u044c\u0448\u0435. \u041e\u0431\u044b\u0447\u043d\u043e \u0441\u0442\u043e\u0438\u0442 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 cmp \u0438\u043b\u0438 test (9.7). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: jpe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 PF", "\u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 PF = 1 (\u0447\u0430\u0441\u0442\u043e: NaN)", "9.6,9.8");
