		rec("lahf", "load AH from flags", "\u043b\u043e\u0443\u0434 \u044d\u0439-\u044d\u0439\u0447 \u0444\u0440\u043e\u043c \u0444\u043b\u044d\u0433\u0437", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c AH \u0438\u0437 \u0444\u043b\u0430\u0433\u043e\u0432", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043c\u043b\u0430\u0434\u0448\u0438\u0435 \u0444\u043b\u0430\u0433\u0438 (SF, ZF, CF \u0438 \u0434\u0440\u0443\u0433\u0438\u0435) \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 AH.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u043b\u0430\u0434\u0448\u0438\u0435 \u0444\u043b\u0430\u0433\u0438 \u2192 AH", "9.6");
