		rec("leave", "leave", "\u043b\u0438\u0432", "\u043f\u043e\u043a\u0438\u043d\u0443\u0442\u044c", "\u0420\u0430\u0437\u0431\u0438\u0440\u0430\u0435\u0442 \u043a\u0430\u0434\u0440 \u0441\u0442\u0435\u043a\u0430: \u0442\u043e \u0436\u0435, \u0447\u0442\u043e mov rsp, rbp \u0438 pop rbp. \u0421\u0442\u043e\u0438\u0442 \u043f\u0435\u0440\u0435\u0434 ret \u0432 \u0444\u0443\u043d\u043a\u0446\u0438\u044f\u0445 \u0441 \u043a\u0430\u0434\u0440\u043e\u043c.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "= mov rsp, rbp + pop rbp", "11.6");
