		rec("lgdt", "load global descriptor table register", "\u043b\u043e\u0443\u0434 \u0433\u043b\u043e\u0443\u0431\u044d\u043b \u0434\u0438\u0441\u043a\u0440\u0438\u043f\u0442\u044d\u0440 \u0442\u044d\u0439\u0431\u043b \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b GDT", "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u0430\u0434\u0440\u0435\u0441 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u043e\u0432 GDT (33.7). \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0437\u0430\u0434\u0430\u0442\u044c \u0430\u0434\u0440\u0435\u0441 \u0442\u0430\u0431\u043b\u0438\u0446\u044b GDT (\u043a\u043e\u043b\u044c\u0446\u043e 0)", "33.7");
		rec("lidt", "load interrupt descriptor table register", "\u043b\u043e\u0443\u0434 \u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442 \u0434\u0438\u0441\u043a\u0440\u0438\u043f\u0442\u044d\u0440 \u0442\u044d\u0439\u0431\u043b \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b IDT", "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u0430\u0434\u0440\u0435\u0441 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0439 IDT (34.4). \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0437\u0430\u0434\u0430\u0442\u044c \u0430\u0434\u0440\u0435\u0441 \u0442\u0430\u0431\u043b\u0438\u0446\u044b IDT (\u043a\u043e\u043b\u044c\u0446\u043e 0)", "34.4");
		rec("lods", "load string", "\u043b\u043e\u0443\u0434 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0427\u0438\u0442\u0430\u0435\u0442 \u044d\u043b\u0435\u043c\u0435\u043d\u0442 \u0438\u0437 [RSI] \u0432 AL, AX, EAX \u0438\u043b\u0438 RAX \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RSI.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0447\u0438\u0442\u0430\u0435\u0442 [RSI] \u0432 AL/AX/EAX/RAX", "");
		rec("lodsb", "load string", "\u043b\u043e\u0443\u0434 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0427\u0438\u0442\u0430\u0435\u0442 1 \u0431\u0430\u0439\u0442 \u0438\u0437 [RSI] \u0432 AL \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RSI.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0447\u0438\u0442\u0430\u0435\u0442 [RSI] \u0432 AL", "");
		rec("lodsd", "load string", "\u043b\u043e\u0443\u0434 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0427\u0438\u0442\u0430\u0435\u0442 4 \u0431\u0430\u0439\u0442\u0430 \u0438\u0437 [RSI] \u0432 EAX \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RSI.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0447\u0438\u0442\u0430\u0435\u0442 [RSI] \u0432 EAX", "");
