		rec("lodsw", "load string", "\u043b\u043e\u0443\u0434 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0427\u0438\u0442\u0430\u0435\u0442 2 \u0431\u0430\u0439\u0442\u0430 \u0438\u0437 [RSI] \u0432 AX \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RSI.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0447\u0438\u0442\u0430\u0435\u0442 [RSI] \u0432 AX", "");
		rec("loop", "loop", "\u043b\u0443\u043f", "\u0446\u0438\u043a\u043b", "\u0423\u043c\u0435\u043d\u044c\u0448\u0430\u0435\u0442 RCX \u043d\u0430 1 \u0438 \u043f\u0440\u044b\u0433\u0430\u0435\u0442, \u0435\u0441\u043b\u0438 RCX \u043d\u0435 \u0441\u0442\u0430\u043b \u043d\u0443\u043b\u0451\u043c. \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440\u044b \u0435\u0451 \u043f\u043e\u0447\u0442\u0438 \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "RCX \u2212= 1; \u043f\u0440\u044b\u0436\u043e\u043a, \u0435\u0441\u043b\u0438 RCX \u2260 0", "10.9");
		rec("lzcnt", "count leading zero bits", "\u043a\u0430\u0443\u043d\u0442 \u043b\u0438\u0434\u0438\u043d\u0433 \u0437\u0438\u0440\u043e\u0443 \u0431\u0438\u0442\u0441", "\u0441\u043e\u0441\u0447\u0438\u0442\u0430\u0442\u044c \u043d\u0443\u043b\u0438 \u0432 \u0441\u0442\u0430\u0440\u0448\u0438\u0445 \u0431\u0438\u0442\u0430\u0445", "\u0421\u0447\u0438\u0442\u0430\u0435\u0442 \u043d\u0443\u043b\u0435\u0432\u044b\u0435 \u0431\u0438\u0442\u044b \u0441\u043e \u0441\u0442\u0430\u0440\u0448\u0435\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0434\u043e \u043f\u0435\u0440\u0432\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u044b. \u0414\u043b\u044f \u043d\u0443\u043b\u044f \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 \u0434\u0430\u0451\u0442 \u0440\u0430\u0437\u043c\u0435\u0440 \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430 \u0432 \u0431\u0438\u0442\u0430\u0445 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 CF = 1.", "CF = 1, \u0435\u0441\u043b\u0438 \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 0; ZF = 1, \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 0", "\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0443\u043b\u0435\u0439 \u0434\u043e \u043f\u0435\u0440\u0432\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u0441\u0432\u0435\u0440\u0445\u0443", "");
		rec("maxpd", "maximum packed double", "\u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "\u0411\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("maxps", "maximum packed single", "\u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "\u0411\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("maxsd", "maximum scalar double", "\u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u0411\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "12.2");
		rec("maxss", "maximum scalar single", "\u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u0411\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "12.2");
		rec("mfence", "memory fence", "\u043c\u044d\u043c\u043e\u0440\u0438 \u0444\u044d\u043d\u0441", "\u0431\u0430\u0440\u044c\u0435\u0440 \u043f\u0430\u043c\u044f\u0442\u0438", "\u0411\u0430\u0440\u044c\u0435\u0440: \u0432\u0441\u0435 \u0447\u0442\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u043f\u0438\u0441\u0438 \u043f\u0430\u043c\u044f\u0442\u0438 \u0434\u043e \u043d\u0435\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u0447\u0430\u0442\u0441\u044f \u0440\u0430\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u043d\u0430\u0447\u043d\u0443\u0442\u0441\u044f \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0435.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u0430\u0440\u044c\u0435\u0440: \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u0442\u044c \u0447\u0442\u0435\u043d\u0438\u044f \u0438 \u0437\u0430\u043f\u0438\u0441\u0438", "");
		rec("minpd", "minimum packed double", "\u043c\u0438\u043d\u0438\u043c\u0443\u043c \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "\u041c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("minps", "minimum packed single", "\u043c\u0438\u043d\u0438\u043c\u0443\u043c \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "\u041c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("minsd", "minimum scalar double", "\u043c\u0438\u043d\u0438\u043c\u0443\u043c \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u041c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "12.2");
		rec("minss", "minimum scalar single", "\u043c\u0438\u043d\u0438\u043c\u0443\u043c \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u041c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u0435\u043d\u044c\u0448\u0435\u0435 \u0438\u0437 \u0434\u0432\u0443\u0445, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "12.2");
		rec("mov", "move", "\u043c\u0443\u0432", "\u043f\u0435\u0440\u0435\u043c\u0435\u0441\u0442\u0438\u0442\u044c", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: mov \u043a\u0443\u0434\u0430, \u043e\u0442\u043a\u0443\u0434\u0430. \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043a\u0430\u043a \u0431\u044b\u043b. \u041a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0435 \u0441\u043a\u043e\u0431\u043a\u0438 \u2014 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043a \u043f\u0430\u043c\u044f\u0442\u0438 (10.3).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442: \u043a\u0443\u0434\u0430 \u2190 \u043e\u0442\u043a\u0443\u0434\u0430", "10.2");
		rec("movapd", "move aligned packed double", "\u043c\u0443\u0432 \u044d\u043b\u0430\u0439\u043d\u0434 \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u043d\u044b\u0435 16 \u0431\u0430\u0439\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c\u0438 xmm \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e. \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0442\u0430\u043a \u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0438 \u043e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u043b\u044e\u0431\u044b\u0435 16-\u0431\u0430\u0439\u0442\u043e\u0432\u044b\u0435 \u043a\u0443\u0441\u043a\u0438, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430. \u0410\u0434\u0440\u0435\u0441 \u0432 \u043f\u0430\u043c\u044f\u0442\u0438 \u043e\u0431\u044f\u0437\u0430\u043d \u0434\u0435\u043b\u0438\u0442\u044c\u0441\u044f \u043d\u0430 16 (\u041f2.6), \u0438\u043d\u0430\u0447\u0435 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u0443\u043f\u0430\u0434\u0451\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 (\u0430\u0434\u0440\u0435\u0441 \u043a\u0440\u0430\u0442\u0435\u043d 16)", "\u041f2.6");
		rec("movaps", "move aligned packed single", "\u043c\u0443\u0432 \u044d\u043b\u0430\u0439\u043d\u0434 \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u043d\u044b\u0435 16 \u0431\u0430\u0439\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c\u0438 xmm \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e. \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0442\u0430\u043a \u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0438 \u043e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u043b\u044e\u0431\u044b\u0435 16-\u0431\u0430\u0439\u0442\u043e\u0432\u044b\u0435 \u043a\u0443\u0441\u043a\u0438, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430. \u0410\u0434\u0440\u0435\u0441 \u0432 \u043f\u0430\u043c\u044f\u0442\u0438 \u043e\u0431\u044f\u0437\u0430\u043d \u0434\u0435\u043b\u0438\u0442\u044c\u0441\u044f \u043d\u0430 16 (\u041f2.6), \u0438\u043d\u0430\u0447\u0435 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u0443\u043f\u0430\u0434\u0451\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 (\u0430\u0434\u0440\u0435\u0441 \u043a\u0440\u0430\u0442\u0435\u043d 16)", "\u041f2.6");
		rec("movbe", "move data after swapping bytes", "\u043c\u0443\u0432 \u0434\u044d\u0439\u0442\u0430 \u0430\u0444\u0442\u044d\u0440 \u0441\u0432\u043e\u043f\u043f\u0438\u043d\u0433 \u0431\u0430\u0439\u0442\u0441", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0432 \u0431\u0430\u0439\u0442\u044b", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e, \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0431\u0430\u0439\u0442\u043e\u0432: mov \u0438 bswap \u0437\u0430 \u043e\u0434\u0438\u043d \u0440\u0430\u0437 (3.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0441 \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u043e\u0442\u043e\u043c \u0431\u0430\u0439\u0442\u043e\u0432", "3.7");
		rec("movd", "move doubleword", "\u043c\u0443\u0432 \u0434\u0430\u0431\u043b\u0443\u043e\u0440\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u0432\u043e\u0439\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 4 \u0431\u0430\u0439\u0442\u0430 \u043c\u0435\u0436\u0434\u0443 \u043e\u0431\u044b\u0447\u043d\u044b\u043c \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c (\u0438\u043b\u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e) \u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c xmm.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "4 \u0431\u0430\u0439\u0442\u0430: \u043e\u0431\u044b\u0447\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u2194 xmm", "12.2");
		rec("movdqa", "move aligned double quadword", "\u043c\u0443\u0432 \u044d\u043b\u0430\u0439\u043d\u0434 \u0434\u0430\u0431\u043b \u043a\u0443\u043e\u0434\u0443\u043e\u0440\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u043d\u044b\u0435 16 \u0431\u0430\u0439\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 xmm \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e; \u0430\u0434\u0440\u0435\u0441 \u043e\u0431\u044f\u0437\u0430\u043d \u0434\u0435\u043b\u0438\u0442\u044c\u0441\u044f \u043d\u0430 16 (\u041f2.6).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 (\u0430\u0434\u0440\u0435\u0441 \u043a\u0440\u0430\u0442\u0435\u043d 16)", "\u041f2.6");
		rec("movdqu", "move unaligned double quadword", "\u043c\u0443\u0432 \u0430\u043d\u044d\u043b\u0430\u0439\u043d\u0434 \u0434\u0430\u0431\u043b \u043a\u0443\u043e\u0434\u0443\u043e\u0440\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043d\u0435\u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u043d\u044b\u0435 16 \u0431\u0430\u0439\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 xmm \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e, \u0430\u0434\u0440\u0435\u0441 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043b\u044e\u0431\u044b\u043c.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 (\u043b\u044e\u0431\u043e\u0439 \u0430\u0434\u0440\u0435\u0441)", "12.2");
		rec("movq", "move quadword", "\u043c\u0443\u0432 \u043a\u0443\u043e\u0434\u0443\u043e\u0440\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0447\u0435\u0442\u0432\u0435\u0440\u043d\u043e\u0435 \u0441\u043b\u043e\u0432\u043e", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 8 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 \u043e\u0431\u044b\u0447\u043d\u044b\u043c \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c (\u0438\u043b\u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e) \u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c xmm.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "8 \u0431\u0430\u0439\u0442: \u043e\u0431\u044b\u0447\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u2194 xmm", "12.2");
		rec("movs", "move string", "\u043c\u0443\u0432 \u0441\u0442\u0440\u0438\u043d\u0433", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u044d\u043b\u0435\u043c\u0435\u043d\u0442 \u0438\u0437 [RSI] \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442 RCX \u0440\u0430\u0437 \u2014 \u044d\u0442\u043e memcpy, \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 \u043f\u0440\u044f\u043c\u043e \u0432 \u043a\u043e\u0434.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 [RSI] \u2192 [RDI]", "");
		rec("movsb", "move string", "\u043c\u0443\u0432 \u0441\u0442\u0440\u0438\u043d\u0433", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 1 \u0431\u0430\u0439\u0442 \u0438\u0437 [RSI] \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442 RCX \u0440\u0430\u0437 \u2014 \u044d\u0442\u043e memcpy, \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 \u043f\u0440\u044f\u043c\u043e \u0432 \u043a\u043e\u0434.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 1 \u0431\u0430\u0439\u0442: [RSI] \u2192 [RDI]", "");
		rec("movsd.sse", "move scalar double", "\u043c\u0443\u0432 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043e\u0434\u043d\u043e \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442) \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 xmm \u0438\u043b\u0438 \u0438\u0437 \u043d\u0435\u0433\u043e. \u041e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e: \u0431\u0435\u0437 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u0432 xmm \u0442\u043e \u0436\u0435 \u0438\u043c\u044f \u0437\u043d\u0430\u0447\u0438\u0442 \u0441\u043e\u0432\u0441\u0435\u043c \u0434\u0440\u0443\u0433\u043e\u0435 \u2014 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0441\u0442\u0440\u043e\u043a\u0438 (movsd, \u043a\u0430\u043a movsb).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442)", "12.2");
		rec("movsd.str", "move string doubleword", "\u043c\u0443\u0432 \u0441\u0442\u0440\u0438\u043d\u0433 \u0434\u0430\u0431\u043b\u0443\u043e\u0440\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443 \u043f\u043e 4 \u0431\u0430\u0439\u0442\u0430", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 4 \u0431\u0430\u0439\u0442\u0430 \u0438\u0437 [RSI] \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. \u0421 rep \u2014 memcpy \u043f\u043e 4 \u0431\u0430\u0439\u0442\u0430. \u041e\u0441\u0442\u043e\u0440\u043e\u0436\u043d\u043e: \u0441 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c\u0438 xmm \u0442\u043e \u0436\u0435 \u0438\u043c\u044f \u0437\u043d\u0430\u0447\u0438\u0442 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0447\u0438\u0441\u043b\u0430 double.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 4 \u0431\u0430\u0439\u0442\u0430 [RSI] \u2192 [RDI]", "");
		rec("movsq", "move string", "\u043c\u0443\u0432 \u0441\u0442\u0440\u0438\u043d\u0433", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 8 \u0431\u0430\u0439\u0442 \u0438\u0437 [RSI] \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442 RCX \u0440\u0430\u0437 \u2014 \u044d\u0442\u043e memcpy, \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 \u043f\u0440\u044f\u043c\u043e \u0432 \u043a\u043e\u0434.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 8 \u0431\u0430\u0439\u0442: [RSI] \u2192 [RDI]", "");
		rec("movss", "move scalar single", "\u043c\u0443\u0432 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043e\u0434\u043d\u043e \u0434\u0440\u043e\u0431\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430) \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 xmm \u0438\u043b\u0438 \u0438\u0437 \u043d\u0435\u0433\u043e. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u044b \u0444\u0443\u043d\u043a\u0446\u0438\u0439 \u0438\u0434\u0443\u0442 \u0432 xmm0\u2013xmm3 (12.2).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430)", "12.2");
		rec("movsw", "move string", "\u043c\u0443\u0432 \u0441\u0442\u0440\u0438\u043d\u0433", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 2 \u0431\u0430\u0439\u0442\u0430 \u0438\u0437 [RSI] \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043e\u0431\u0430 \u0443\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442 RCX \u0440\u0430\u0437 \u2014 \u044d\u0442\u043e memcpy, \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0439 \u043f\u0440\u044f\u043c\u043e \u0432 \u043a\u043e\u0434.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 2 \u0431\u0430\u0439\u0442\u0430: [RSI] \u2192 [RDI]", "");
		rec("movsx", "move with sign extend", "\u043c\u0443\u0432 \u0443\u0438\u0437 \u0441\u0430\u0439\u043d \u044d\u043a\u0441\u0442\u044d\u043d\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435\u043c \u0437\u043d\u0430\u043a\u0430", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0432 \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0441 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435\u043c \u0437\u043d\u0430\u043a\u0430: \u0443 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u0431\u0438\u0442\u044b \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u044e\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438. \u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u043e \u0442\u0438\u043f\u0435: \u0447\u0438\u0441\u043b\u043e \u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043c\u0430\u043b\u043e\u0435 \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "10.2");
		rec("movsxd", "move with sign extend doubleword", "\u043c\u0443\u0432 \u0443\u0438\u0437 \u0441\u0430\u0439\u043d \u044d\u043a\u0441\u0442\u044d\u043d\u0434 \u0434\u0430\u0431\u043b\u0443\u043e\u0440\u0434", "\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c 4 \u0431\u0430\u0439\u0442\u0430 \u0434\u043e 8 \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "\u0411\u0435\u0440\u0451\u0442 4-\u0431\u0430\u0439\u0442\u043e\u0432\u043e\u0435 \u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0438 \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u0435\u0442 \u0435\u0433\u043e \u0434\u043e 8 \u0431\u0430\u0439\u0442. \u0427\u0430\u0441\u0442\u043e \u0441\u0442\u043e\u0438\u0442 \u0442\u0430\u043c, \u0433\u0434\u0435 int \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u0438\u043d\u0434\u0435\u043a\u0441\u043e\u043c \u043c\u0430\u0441\u0441\u0438\u0432\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "4 \u0431\u0430\u0439\u0442\u0430 \u2192 8 \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c (int \u2192 \u0438\u043d\u0434\u0435\u043a\u0441)", "10.2,18.4");
		rec("movupd", "move unaligned packed double", "\u043c\u0443\u0432 \u0430\u043d\u044d\u043b\u0430\u0439\u043d\u0434 \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043d\u0435\u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u043d\u044b\u0435 16 \u0431\u0430\u0439\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c\u0438 xmm \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e, \u0430\u0434\u0440\u0435\u0441 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043b\u044e\u0431\u044b\u043c. \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0442\u0430\u043a \u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043a\u0443\u0441\u043a\u0438 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440 \u0438 \u0441\u0442\u0440\u043e\u043a.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 (\u043b\u044e\u0431\u043e\u0439 \u0430\u0434\u0440\u0435\u0441)", "12.2");
		rec("movups", "move unaligned packed single", "\u043c\u0443\u0432 \u0430\u043d\u044d\u043b\u0430\u0439\u043d\u0434 \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043d\u0435\u0432\u044b\u0440\u043e\u0432\u043d\u0435\u043d\u043d\u044b\u0435 16 \u0431\u0430\u0439\u0442", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 \u043c\u0435\u0436\u0434\u0443 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c\u0438 xmm \u0438 \u043f\u0430\u043c\u044f\u0442\u044c\u044e, \u0430\u0434\u0440\u0435\u0441 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043b\u044e\u0431\u044b\u043c. \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0442\u0430\u043a \u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043a\u0443\u0441\u043a\u0438 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440 \u0438 \u0441\u0442\u0440\u043e\u043a.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 16 \u0431\u0430\u0439\u0442 (\u043b\u044e\u0431\u043e\u0439 \u0430\u0434\u0440\u0435\u0441)", "12.2");
		rec("movzx", "move with zero extend", "\u043c\u0443\u0432 \u0443\u0438\u0437 \u0437\u0438\u0440\u043e\u0443 \u044d\u043a\u0441\u0442\u044d\u043d\u0434", "\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0432 \u043d\u0443\u043b\u044f\u043c\u0438", "\u041a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u0431\u0430\u0439\u0442 \u0438\u043b\u0438 \u0434\u0432\u0430 \u0431\u0430\u0439\u0442\u0430 \u0432 \u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440, \u0430 \u043b\u0438\u0448\u043d\u0438\u0435 \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u0431\u0438\u0442\u044b \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 \u043d\u0443\u043b\u044f\u043c\u0438. \u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u043e \u0442\u0438\u043f\u0435: \u0447\u0438\u0441\u043b\u043e \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u043e\u043f\u0438\u0440\u0443\u0435\u0442 \u043c\u0430\u043b\u043e\u0435, \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u0431\u0438\u0442\u044b \u2014 \u043d\u0443\u043b\u0438", "10.2");
		rec("mul", "multiply", "\u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0430\u0439", "\u0443\u043c\u043d\u043e\u0436\u0438\u0442\u044c (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u0411\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0441 \u043e\u0434\u043d\u0438\u043c \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u043e\u043c: RDX:RAX = RAX * \u043e\u043f\u0435\u0440\u0430\u043d\u0434 (\u0434\u043b\u044f 4 \u0431\u0430\u0439\u0442 \u2014 EDX:EAX). \u0421\u0442\u0430\u0440\u0448\u0430\u044f \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 RDX. \u0427\u0430\u0441\u0442\u043e \u044d\u0442\u043e \u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u0443 \u0447\u0435\u0440\u0435\u0437 \u00ab\u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0435\u00bb \u0447\u0438\u0441\u043b\u043e (10.5, \u0433\u043b\u0430\u0432\u0430 18).", "CF \u0438 OF = 1, \u0435\u0441\u043b\u0438 \u0441\u0442\u0430\u0440\u0448\u0430\u044f \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u043d\u0435 \u043d\u043e\u043b\u044c", "RDX:RAX = RAX * \u043e\u043f\u0435\u0440\u0430\u043d\u0434", "10.5");
		rec("mulpd", "multiply packed double", "\u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0430\u0439 \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "\u0423\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435, \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("mulps", "multiply packed single", "\u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0430\u0439 \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "\u0423\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435, \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("mulsd", "multiply scalar double", "\u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0430\u0439 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u0423\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "12.2");
		rec("mulss", "multiply scalar single", "\u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0430\u0439 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u0423\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "12.2");
		rec("neg", "negate", "\u043d\u0438\u0433\u0435\u0439\u0442", "\u0441\u043c\u0435\u043d\u0438\u0442\u044c \u0437\u043d\u0430\u043a", "\u041c\u0435\u043d\u044f\u0435\u0442 \u0437\u043d\u0430\u043a \u0447\u0438\u0441\u043b\u0430: a = 0 \u2212 a.", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435; CF = 1, \u0435\u0441\u043b\u0438 a \u0431\u044b\u043b\u043e \u043d\u0435 \u043d\u0443\u043b\u0451\u043c", "a = \u2212a", "10.5");
		rec("nop", "no operation", "\u043d\u043e\u0443 \u043e\u043f\u044d\u0440\u0435\u0439\u0448\u043d", "\u043d\u0435\u0442 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438", "\u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442. \u0414\u043b\u0438\u043d\u043d\u044b\u0435 nop \u0441 \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430\u043c\u0438 \u0432\u0440\u043e\u0434\u0435 [rax+rax] \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0441\u0442\u0430\u0432\u0438\u0442, \u0447\u0442\u043e\u0431\u044b \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u043a\u043e\u0434 \u043d\u0430\u0447\u0438\u043d\u0430\u043b\u0441\u044f \u0441 \u0440\u043e\u0432\u043d\u043e\u0433\u043e \u0430\u0434\u0440\u0435\u0441\u0430. gcc \u043f\u043e\u0434 Windows \u0441\u0442\u0430\u0432\u0438\u0442 nop \u0438 \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 call, \u0435\u0441\u043b\u0438 \u0434\u0430\u043b\u044c\u0448\u0435 \u043a\u043e\u043d\u0435\u0446 \u0444\u0443\u043d\u043a\u0446\u0438\u0438, \u2014 \u0442\u0430\u043a \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0439. \u041f\u0440\u0438 \u0447\u0442\u0435\u043d\u0438\u0438 \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0430\u0442\u044c.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0434\u0435\u043b\u0430\u0435\u0442 (\u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435)", "10.7");
		rec("not", "not", "\u043d\u043e\u0442", "\u043d\u0435", "\u041f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0432\u0441\u0435 \u0431\u0438\u0442\u044b: 0 \u2194 1.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0432\u0441\u0435 \u0431\u0438\u0442\u044b", "10.6");
		rec("or", "or", "\u043e\u0440", "\u0438\u043b\u0438", "\u041f\u043e\u0431\u0438\u0442\u043e\u0432\u043e\u0435 \u0418\u041b\u0418: \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043d\u0443\u0436\u043d\u044b\u0435 \u0431\u0438\u0442\u044b. or eax, -1 \u0434\u0435\u043b\u0430\u0435\u0442 EAX = \u22121 (\u0432\u0441\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u044b).", "CF = OF = 0; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u043f\u043e\u0431\u0438\u0442\u043e\u0432\u043e\u0435 \u0418\u041b\u0418", "10.6");
		rec("paddb", "packed integer arithmetic", "\u043f\u044d\u043a\u0442 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440 \u044d\u0440\u0438\u0444\u043c\u044d\u0442\u0438\u043a", "\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430 \u043d\u0430\u0434 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438 \u0441\u0440\u0430\u0437\u0443", "\u0412\u0435\u043a\u0442\u043e\u0440\u043d\u0430\u044f \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u044f: \u043e\u0434\u043d\u043e \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 (\u0441\u043b\u043e\u0436\u0435\u043d\u0438\u0435, \u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435, \u0441\u0434\u0432\u0438\u0433 \u0438 \u0434\u0440\u0443\u0433\u0438\u0435) \u0441\u0440\u0430\u0437\u0443 \u043d\u0430\u0434 \u0432\u0441\u0435\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438 \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0435 xmm.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043d\u0430\u0434 \u0432\u0441\u0435\u043c\u0438 \u0447\u0438\u0441\u043b\u0430\u043c\u0438 \u0432 xmm \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("pand", "logical and (packed)", "\u043b\u043e\u0434\u0436\u0438\u043a\u044d\u043b \u044d\u043d\u0434", "\u0418 \u043d\u0430\u0434 16 \u0431\u0430\u0439\u0442\u0430\u043c\u0438", "\u041f\u043e\u0431\u0438\u0442\u043e\u0432\u043e\u0435 \u0418 \u043d\u0430\u0434 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c xmm. \u0421 \u043c\u0430\u0441\u043a\u043e\u0439 \u0442\u0430\u043a \u0431\u0435\u0440\u0443\u0442 \u043c\u043e\u0434\u0443\u043b\u044c \u0434\u0440\u043e\u0431\u043d\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430: \u0443\u0431\u0438\u0440\u0430\u044e\u0442 \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0431\u0438\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0418 \u043d\u0430\u0434 xmm (\u0447\u0430\u0441\u0442\u043e \u2014 \u043c\u043e\u0434\u0443\u043b\u044c \u0447\u0438\u0441\u043b\u0430)", "10.6");
		rec("pandn", "logical and not (packed)", "\u043b\u043e\u0434\u0436\u0438\u043a\u044d\u043b \u044d\u043d\u0434 \u043d\u043e\u0442", "\u0418-\u041d\u0415 \u043d\u0430\u0434 16 \u0431\u0430\u0439\u0442\u0430\u043c\u0438", "\u041f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442 \u0431\u0438\u0442\u044b \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430 \u0438 \u0434\u0435\u043b\u0430\u0435\u0442 \u0418 \u0441\u043e \u0432\u0442\u043e\u0440\u044b\u043c.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "(\u041d\u0415 a) \u0418 b \u043d\u0430\u0434 xmm", "10.6");
		rec("pause", "pause", "\u043f\u043e\u0437", "\u043f\u0430\u0443\u0437\u0430", "\u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0443: \u0438\u0434\u0451\u0442 \u0446\u0438\u043a\u043b \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f (\u0441\u043f\u0438\u043d-\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u043a\u0430). \u0411\u0435\u0440\u0435\u0436\u0451\u0442 \u0441\u0438\u043b\u044b \u044f\u0434\u0440\u0430 (\u041f3.6).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430: \u044d\u0442\u043e \u0446\u0438\u043a\u043b \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f", "\u041f3.6");
		rec("pclmulqdq", "carry-less multiplication quadword", "\u043a\u044d\u0440\u0438-\u043b\u044d\u0441 \u043c\u0430\u043b\u0442\u0438\u043f\u043b\u0438\u043a\u0435\u0439\u0448\u043d \u043a\u0443\u043e\u0434\u0443\u043e\u0440\u0434", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u043e\u0432", "\u0423\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u043e\u0432. \u0418\u043c \u0431\u044b\u0441\u0442\u0440\u043e \u0441\u0447\u0438\u0442\u0430\u044e\u0442 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0441\u0443\u043c\u043c\u044b CRC \u0438 \u0440\u0435\u0436\u0438\u043c \u0448\u0438\u0444\u0440\u043e\u0432\u0430\u043d\u0438\u044f GCM.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u043e\u0432 (CRC, GCM)", "");
		rec("pcmpeqb", "compare packed data for equal", "\u043a\u044d\u043c\u043f\u0435\u0440 \u043f\u044d\u043a\u0442 \u0434\u044d\u0439\u0442\u0430 \u0444\u043e \u0438\u043a\u0432\u044d\u043b", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u043d\u0430 \u0440\u0430\u0432\u0435\u043d\u0441\u0442\u0432\u043e \u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e (\u043f\u043e 1, 2, 4 \u0438\u043b\u0438 8 \u0431\u0430\u0439\u0442): \u0440\u0430\u0432\u043d\u044b\u0435 \u043c\u0435\u0441\u0442\u0430 \u0441\u0442\u0430\u043d\u043e\u0432\u044f\u0442\u0441\u044f \u0432\u0441\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u044b, \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u2014 \u043d\u0443\u043b\u0438. \u0412\u043c\u0435\u0441\u0442\u0435 \u0441 pmovmskb \u0442\u0430\u043a \u0438\u0449\u0443\u0442 \u043d\u043e\u043b\u044c \u0432 \u0441\u0442\u0440\u043e\u043a\u0435 (\u0431\u044b\u0441\u0442\u0440\u044b\u0439 strlen).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043d\u0430 \u0440\u0430\u0432\u0435\u043d\u0441\u0442\u0432\u043e", "12.2");
		rec("pcmpgtb", "compare packed signed integers for greater than", "\u043a\u044d\u043c\u043f\u0435\u0440 \u043f\u044d\u043a\u0442 \u0441\u0430\u0439\u043d\u0434 \u0438\u043d\u0442\u0438\u0434\u0436\u0435\u0440\u0437 \u0444\u043e \u0433\u0440\u044d\u0439\u0442\u044d\u0440 \u0437\u044d\u043d", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u00ab\u0431\u043e\u043b\u044c\u0448\u0435\u00bb \u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e \u043a\u0430\u043a \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u0447\u0438\u0441\u043b\u0430: \u0433\u0434\u0435 \u043f\u0435\u0440\u0432\u043e\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0432\u0441\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u044b, \u0438\u043d\u0430\u0447\u0435 \u043d\u0443\u043b\u0438.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043d\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u00ab\u0431\u043e\u043b\u044c\u0448\u0435\u00bb", "12.2");
		rec("pmovmskb", "move byte mask", "\u043c\u0443\u0432 \u0431\u0430\u0439\u0442 \u043c\u0430\u0441\u043a", "\u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043c\u0430\u0441\u043a\u0443", "\u0421\u043e\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u0431\u0438\u0442\u044b \u0432\u0441\u0435\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430 xmm \u0432 \u043e\u0431\u044b\u0447\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440. \u041f\u043e\u0441\u043b\u0435 pcmpeqb \u0434\u0430\u0451\u0442 \u043d\u043e\u043c\u0435\u0440 \u043d\u0430\u0439\u0434\u0435\u043d\u043d\u043e\u0433\u043e \u0431\u0430\u0439\u0442\u0430 (\u0447\u0435\u0440\u0435\u0437 bsf \u0438\u043b\u0438 tzcnt).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u0431\u0438\u0442\u044b \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 xmm \u2192 \u043e\u0431\u044b\u0447\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440", "12.2");
		rec("pop", "pop", "\u043f\u043e\u043f", "\u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044c", "\u0421\u043d\u0438\u043c\u0430\u0435\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0441 \u0432\u0435\u0440\u0448\u0438\u043d\u044b \u0441\u0442\u0435\u043a\u0430: \u0431\u0435\u0440\u0451\u0442 [RSP] \u0432 \u043e\u043f\u0435\u0440\u0430\u043d\u0434, \u043f\u043e\u0442\u043e\u043c RSP \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430 8.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0441\u043d\u044f\u0442\u044c \u0441\u043e \u0441\u0442\u0435\u043a\u0430 (RSP += 8)", "10.8");
		rec("popcnt", "population count", "\u043f\u043e\u043f\u044c\u044e\u043b\u0435\u0439\u0448\u043d \u043a\u0430\u0443\u043d\u0442", "\u043f\u043e\u0434\u0441\u0447\u0451\u0442 \u0435\u0434\u0438\u043d\u0438\u0446", "\u0421\u0447\u0438\u0442\u0430\u0435\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0442\u043e\u0432 \u0432 \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0435 \u0440\u0430\u0432\u043d\u043e 1.", "ZF = 1, \u0435\u0441\u043b\u0438 \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 0; \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u0431\u0440\u043e\u0448\u0435\u043d\u044b", "\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0442\u043e\u0432 \u0440\u0430\u0432\u043d\u043e 1", "");
		rec("popfq", "pop flags (quadword)", "\u043f\u043e\u043f \u0444\u043b\u044d\u0433\u0437", "\u0441\u043d\u044f\u0442\u044c \u0444\u043b\u0430\u0433\u0438 \u0441\u043e \u0441\u0442\u0435\u043a\u0430", "\u0421\u043d\u0438\u043c\u0430\u0435\u0442 \u0441\u043e \u0441\u0442\u0435\u043a\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0444\u043b\u0430\u0433\u043e\u0432 RFLAGS (9.6).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435: \u0431\u0435\u0440\u0451\u0442 \u0438\u0445 \u0441\u043e \u0441\u0442\u0435\u043a\u0430", "\u0441\u043d\u044f\u0442\u044c RFLAGS \u0441\u043e \u0441\u0442\u0435\u043a\u0430", "9.6");
		rec("por", "logical or (packed)", "\u043b\u043e\u0434\u0436\u0438\u043a\u044d\u043b \u043e\u0440", "\u0418\u041b\u0418 \u043d\u0430\u0434 16 \u0431\u0430\u0439\u0442\u0430\u043c\u0438", "\u041f\u043e\u0431\u0438\u0442\u043e\u0432\u043e\u0435 \u0418\u041b\u0418 \u043d\u0430\u0434 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u043c xmm.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0418\u041b\u0418 \u043d\u0430\u0434 xmm", "10.6");
		rec("prefetch", "prefetch", "\u043f\u0440\u0438\u0444\u044d\u0442\u0447", "\u043f\u043e\u0434\u0442\u044f\u043d\u0443\u0442\u044c \u0437\u0430\u0440\u0430\u043d\u0435\u0435", "\u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0443: \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043f\u043e\u0434\u0442\u044f\u043d\u0443\u0442\u044c \u0434\u0430\u043d\u043d\u044b\u0435 \u0432 \u043a\u044d\u0448. \u041d\u0430 \u0441\u043c\u044b\u0441\u043b \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430: \u043f\u043e\u0434\u0442\u044f\u043d\u0443\u0442\u044c \u0434\u0430\u043d\u043d\u044b\u0435 \u0432 \u043a\u044d\u0448", "");
		rec("push", "push", "\u043f\u0443\u0448", "\u0432\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044c", "\u041a\u043b\u0430\u0434\u0451\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043d\u0430 \u0432\u0435\u0440\u0448\u0438\u043d\u0443 \u0441\u0442\u0435\u043a\u0430: RSP \u0443\u043c\u0435\u043d\u044c\u0448\u0430\u0435\u0442\u0441\u044f \u043d\u0430 8, \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443 [RSP].", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c \u043d\u0430 \u0441\u0442\u0435\u043a (RSP \u2212= 8)", "10.8");
		rec("pushfq", "push flags (quadword)", "\u043f\u0443\u0448 \u0444\u043b\u044d\u0433\u0437", "\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c \u0444\u043b\u0430\u0433\u0438 \u043d\u0430 \u0441\u0442\u0435\u043a", "\u041a\u043b\u0430\u0434\u0451\u0442 \u043d\u0430 \u0441\u0442\u0435\u043a \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0444\u043b\u0430\u0433\u043e\u0432 RFLAGS (9.6).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c RFLAGS \u043d\u0430 \u0441\u0442\u0435\u043a", "9.6");
		rec("pxor", "logical exclusive or (packed)", "\u043b\u043e\u0434\u0436\u0438\u043a\u044d\u043b \u0438\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0432 \u043e\u0440", "\u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0435\u0435 \u0418\u041b\u0418 \u043d\u0430\u0434 16 \u0431\u0430\u0439\u0442\u0430\u043c\u0438", "\u0418\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0435\u0435 \u0418\u041b\u0418 \u043d\u0430\u0434 \u0432\u0441\u0435\u043c\u0438 16 \u0431\u0430\u0439\u0442\u0430\u043c\u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430 xmm. xorps xmm0, xmm0 \u2014 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430, \u043a\u0430\u043a xor eax, eax (10.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "XOR \u043d\u0430\u0434 xmm; xorps x, x \u2014 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435", "10.7");
		rec("rcl", "rotate through carry left", "\u0440\u043e\u0443\u0442\u0435\u0439\u0442 \u0441\u0440\u0443 \u043a\u044d\u0440\u0438 \u043b\u0435\u0444\u0442", "\u0432\u0440\u0430\u0449\u0430\u0442\u044c \u0432\u043b\u0435\u0432\u043e \u0447\u0435\u0440\u0435\u0437 \u043f\u0435\u0440\u0435\u043d\u043e\u0441", "\u0412\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0432\u043b\u0435\u0432\u043e, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u043f\u043e \u043a\u0440\u0443\u0433\u0443 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0438 \u0444\u043b\u0430\u0433 CF. \u0412\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0440\u0435\u0434\u043a\u043e.", "\u043c\u0435\u043d\u044f\u0435\u0442 CF (\u0438 OF \u043f\u0440\u0438 \u0441\u0434\u0432\u0438\u0433\u0435 \u043d\u0430 1)", "\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0432\u043b\u0435\u0432\u043e \u0447\u0435\u0440\u0435\u0437 CF", "20.5");
		rec("rcr", "rotate through carry right", "\u0440\u043e\u0443\u0442\u0435\u0439\u0442 \u0441\u0440\u0443 \u043a\u044d\u0440\u0438 \u0440\u0430\u0439\u0442", "\u0432\u0440\u0430\u0449\u0430\u0442\u044c \u0432\u043f\u0440\u0430\u0432\u043e \u0447\u0435\u0440\u0435\u0437 \u043f\u0435\u0440\u0435\u043d\u043e\u0441", "\u0412\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0432\u043f\u0440\u0430\u0432\u043e, \u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u043f\u043e \u043a\u0440\u0443\u0433\u0443 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0438 \u0444\u043b\u0430\u0433 CF. \u0412\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0440\u0435\u0434\u043a\u043e.", "\u043c\u0435\u043d\u044f\u0435\u0442 CF (\u0438 OF \u043f\u0440\u0438 \u0441\u0434\u0432\u0438\u0433\u0435 \u043d\u0430 1)", "\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0432\u043f\u0440\u0430\u0432\u043e \u0447\u0435\u0440\u0435\u0437 CF", "20.5");
		rec("rdmsr", "read model-specific register", "\u0440\u0438\u0434 \u043c\u043e\u0434\u044d\u043b-\u0441\u043f\u044d\u0441\u0438\u0444\u0438\u043a \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u043c\u043e\u0434\u0435\u043b\u0438 (MSR)", "\u0427\u0438\u0442\u0430\u0435\u0442 \u043e\u0441\u043e\u0431\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043a MSR \u0441 \u043d\u043e\u043c\u0435\u0440\u043e\u043c \u0438\u0437 ECX \u0432 \u043f\u0430\u0440\u0443 EDX:EAX. \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "MSR[ECX] \u2192 EDX:EAX (\u043a\u043e\u043b\u044c\u0446\u043e 0)", "33.4");
		rec("rdrand", "read random number", "\u0440\u0438\u0434 \u0440\u044d\u043d\u0434\u044d\u043c \u043d\u0430\u043c\u0431\u044d\u0440", "\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e", "\u0411\u0435\u0440\u0451\u0442 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0443 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0432\u043d\u0443\u0442\u0440\u0438 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430. CF = 1, \u0435\u0441\u043b\u0438 \u0447\u0438\u0441\u043b\u043e \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043e.", "CF = 1 \u043f\u0440\u0438 \u0443\u0441\u043f\u0435\u0445\u0435; \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u0431\u0440\u043e\u0448\u0435\u043d\u044b", "\u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u043e\u0442 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430", "");
		rec("rdtsc", "read time-stamp counter", "\u0440\u0438\u0434 \u0442\u0430\u0439\u043c-\u0441\u0442\u044d\u043c\u043f \u043a\u0430\u0443\u043d\u0442\u0435\u0440", "\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0442\u0430\u043a\u0442\u043e\u0432", "\u041a\u043b\u0430\u0434\u0451\u0442 \u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0442\u0430\u043a\u0442\u043e\u0432 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430 \u0432 \u043f\u0430\u0440\u0443 EDX:EAX (\u0441\u0442\u0430\u0440\u0448\u0430\u044f \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u2014 \u0432 EDX). \u0418\u043c \u0442\u043e\u0447\u043d\u043e \u043c\u0435\u0440\u044f\u044e\u0442 \u0432\u0440\u0435\u043c\u044f (\u041f2.8).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0442\u0430\u043a\u0442\u043e\u0432 \u2192 EDX:EAX", "\u041f2.8");
		rec("rdtscp", "read time-stamp counter and processor ID", "\u0440\u0438\u0434 \u0442\u0430\u0439\u043c-\u0441\u0442\u044d\u043c\u043f \u043a\u0430\u0443\u043d\u0442\u0435\u0440 \u044d\u043d\u0434 \u043f\u0440\u043e\u0446\u044d\u0441\u0441\u043e\u0440 \u0430\u0439-\u0434\u0438", "\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0441\u0447\u0451\u0442\u0447\u0438\u043a \u0442\u0430\u043a\u0442\u043e\u0432 \u0438 \u043d\u043e\u043c\u0435\u0440 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430", "\u0422\u043e \u0436\u0435, \u0447\u0442\u043e rdtsc, \u0430 \u0432 ECX \u0435\u0449\u0451 \u043a\u043b\u0430\u0434\u0451\u0442 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435, \u043f\u043e \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0443\u0437\u043d\u0430\u0451\u0442 \u044f\u0434\u0440\u043e (\u041f2.13).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "rdtsc + \u043d\u043e\u043c\u0435\u0440 \u044f\u0434\u0440\u0430 \u0432 ECX", "\u041f2.13");
		rec("ret", "return", "\u0440\u0438\u0442\u0451\u0440\u043d", "\u0432\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f", "\u0421\u043d\u0438\u043c\u0430\u0435\u0442 \u0441\u043e \u0441\u0442\u0435\u043a\u0430 \u0430\u0434\u0440\u0435\u0441 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0430 \u0438 \u043f\u0440\u044b\u0433\u0430\u0435\u0442 \u0442\u0443\u0434\u0430 \u2014 \u043a\u043e\u043d\u0435\u0446 \u0444\u0443\u043d\u043a\u0446\u0438\u0438. \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u043a \u044d\u0442\u043e\u043c\u0443 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u043b\u0435\u0436\u0438\u0442 \u0432 RAX \u0438\u043b\u0438 EAX (12.2).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u0444\u0443\u043d\u043a\u0446\u0438\u0438", "11.2");
		rec("rol", "rotate left", "\u0440\u043e\u0443\u0442\u0435\u0439\u0442 \u043b\u0435\u0444\u0442", "\u0432\u0440\u0430\u0449\u0430\u0442\u044c \u0432\u043b\u0435\u0432\u043e", "\u0421\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e \u043f\u043e \u043a\u0440\u0443\u0433\u0443: \u0431\u0438\u0442\u044b, \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0435 \u0441\u043b\u0435\u0432\u0430, \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0441\u043f\u0440\u0430\u0432\u0430. \u0427\u0430\u0441\u0442\u043e \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0432 \u0448\u0438\u0444\u0440\u0430\u0445 \u0438 \u0445\u0435\u0448\u0430\u0445.", "\u043c\u0435\u043d\u044f\u0435\u0442 CF (\u0438 OF \u043f\u0440\u0438 \u0441\u0434\u0432\u0438\u0433\u0435 \u043d\u0430 1)", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e \u043f\u043e \u043a\u0440\u0443\u0433\u0443", "20.5");
		rec("ror", "rotate right", "\u0440\u043e\u0443\u0442\u0435\u0439\u0442 \u0440\u0430\u0439\u0442", "\u0432\u0440\u0430\u0449\u0430\u0442\u044c \u0432\u043f\u0440\u0430\u0432\u043e", "\u0421\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e \u043f\u043e \u043a\u0440\u0443\u0433\u0443: \u0431\u0438\u0442\u044b, \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0435 \u0441\u043f\u0440\u0430\u0432\u0430, \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0441\u043b\u0435\u0432\u0430. \u041f\u0430\u0440\u0430 \u043a rol.", "\u043c\u0435\u043d\u044f\u0435\u0442 CF (\u0438 OF \u043f\u0440\u0438 \u0441\u0434\u0432\u0438\u0433\u0435 \u043d\u0430 1)", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e \u043f\u043e \u043a\u0440\u0443\u0433\u0443", "20.5");
		rec("sahf", "store AH into flags", "\u0441\u0442\u043e\u0440 \u044d\u0439-\u044d\u0439\u0447 \u0438\u043d\u0442\u0443 \u0444\u043b\u044d\u0433\u0437", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c AH \u0432\u043e \u0444\u043b\u0430\u0433\u0438", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 AH \u0432 \u043c\u043b\u0430\u0434\u0448\u0438\u0435 \u0444\u043b\u0430\u0433\u0438 (SF, ZF, CF \u0438 \u0434\u0440\u0443\u0433\u0438\u0435).", "\u043c\u0435\u043d\u044f\u0435\u0442 SF, ZF, CF \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u043c\u043b\u0430\u0434\u0448\u0438\u0435", "AH \u2192 \u043c\u043b\u0430\u0434\u0448\u0438\u0435 \u0444\u043b\u0430\u0433\u0438", "9.6");
		rec("sal", "shift arithmetic left", "\u0448\u0438\u0444\u0442 \u044d\u0440\u0438\u0444\u043c\u044d\u0442\u0438\u043a \u043b\u0435\u0444\u0442", "\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e", "\u0421\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0431\u0438\u0442\u044b \u0432\u043b\u0435\u0432\u043e \u043d\u0430 n: \u044d\u0442\u043e \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 2 \u0432 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 n. shl eax, 3 \u2014 \u0442\u043e \u0436\u0435, \u0447\u0442\u043e eax * 8.", "CF = \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0439 \u0431\u0438\u0442; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e = \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 2^n", "10.6");
		rec("sar", "shift arithmetic right", "\u0448\u0438\u0444\u0442 \u044d\u0440\u0438\u0444\u043c\u044d\u0442\u0438\u043a \u0440\u0430\u0439\u0442", "\u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e", "\u0421\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0441\u043b\u0435\u0432\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442\u0441\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u0431\u0438\u0442: \u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 2 \u0432 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 n (\u0441 \u043e\u043a\u0440\u0443\u0433\u043b\u0435\u043d\u0438\u0435\u043c \u0432\u043d\u0438\u0437).", "CF = \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0439 \u0431\u0438\u0442; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e \u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c", "10.6");
		rec("sbb", "subtract with borrow", "\u0441\u0430\u0431\u0442\u0440\u044d\u043a\u0442 \u0443\u0438\u0437 \u0431\u043e\u0440\u043e\u0443", "\u0432\u044b\u0447\u0435\u0441\u0442\u044c \u0441 \u0437\u0430\u0451\u043c\u043e\u043c", "a = a \u2212 b \u2212 CF. \u041f\u0440\u0438\u0451\u043c sbb eax, eax \u0434\u0435\u043b\u0430\u0435\u0442 EAX = 0 \u0438\u043b\u0438 \u22121 (\u0432\u0441\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u044b) \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 CF \u2014 \u0442\u0430\u043a \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u043f\u0438\u0448\u0435\u0442 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430.", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435", "a = a \u2212 b \u2212 CF", "9.6");
		rec("scas", "scan string", "\u0441\u043a\u044d\u043d \u0441\u0442\u0440\u0438\u043d\u0433", "\u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 AL, AX, EAX \u0438\u043b\u0438 RAX \u0441 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI. repne scasb \u2014 \u0441\u0442\u0430\u0440\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0430\u0439\u0442\u0438 \u043a\u043e\u043d\u0435\u0446 \u0441\u0442\u0440\u043e\u043a\u0438 (strlen).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 AL/AX/EAX/RAX \u0441 [RDI]", "");
		rec("scasb", "scan string", "\u0441\u043a\u044d\u043d \u0441\u0442\u0440\u0438\u043d\u0433", "\u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 AL \u0441 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI. repne scasb \u2014 \u0441\u0442\u0430\u0440\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0430\u0439\u0442\u0438 \u043a\u043e\u043d\u0435\u0446 \u0441\u0442\u0440\u043e\u043a\u0438 (strlen).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 AL \u0441 [RDI]", "");
		rec("scasd", "scan string", "\u0441\u043a\u044d\u043d \u0441\u0442\u0440\u0438\u043d\u0433", "\u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 EAX \u0441 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI. repne scasb \u2014 \u0441\u0442\u0430\u0440\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0430\u0439\u0442\u0438 \u043a\u043e\u043d\u0435\u0446 \u0441\u0442\u0440\u043e\u043a\u0438 (strlen).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 EAX \u0441 [RDI]", "");
		rec("scasq", "scan string", "\u0441\u043a\u044d\u043d \u0441\u0442\u0440\u0438\u043d\u0433", "\u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 RAX \u0441 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI. repne scasb \u2014 \u0441\u0442\u0430\u0440\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0430\u0439\u0442\u0438 \u043a\u043e\u043d\u0435\u0446 \u0441\u0442\u0440\u043e\u043a\u0438 (strlen).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 RAX \u0441 [RDI]", "");
		rec("scasw", "scan string", "\u0441\u043a\u044d\u043d \u0441\u0442\u0440\u0438\u043d\u0433", "\u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 AX \u0441 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI. repne scasb \u2014 \u0441\u0442\u0430\u0440\u044b\u0439 \u0441\u043f\u043e\u0441\u043e\u0431 \u043d\u0430\u0439\u0442\u0438 \u043a\u043e\u043d\u0435\u0446 \u0441\u0442\u0440\u043e\u043a\u0438 (strlen).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a cmp", "\u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 AX \u0441 [RDI]", "");
		rec("seta", "set byte if above", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0 \u0438 ZF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnbe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setae", "set byte if above or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u2265 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnb, setnc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "1, \u0435\u0441\u043b\u0438 \u2265 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setb", "set byte if below", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setc, setnae.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setbe", "set byte if below or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u2264 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1 \u0438\u043b\u0438 ZF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setna.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "1, \u0435\u0441\u043b\u0438 \u2264 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setc", "set byte if carry", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441, CF = 1", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setb, setnae.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "1, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441, CF = 1, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("sete", "set byte if equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u043e\u043b\u044c (ZF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setz.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "1, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setg", "set byte if greater", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 0 \u0438 SF = OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnle.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setge", "set byte if greater or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u2265 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF = OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnl.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u2265 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setl", "set byte if less", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF \u2260 OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnge.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setle", "set byte if less or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u2264 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 1 \u0438\u043b\u0438 SF \u2260 OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setng.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u2264 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setna", "set byte if not above", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1 \u0438\u043b\u0438 ZF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setbe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnae", "set byte if not above or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setb, setc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "1, \u0435\u0441\u043b\u0438 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnb", "set byte if not below", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setae, setnc.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043d\u0438\u0436\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnbe", "set byte if not below or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0 \u0438 ZF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: seta.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF \u0438 ZF", "1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnc", "set byte if not carry", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, CF = 0", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0432\u044b\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (CF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setae, setnb.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 CF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430, CF = 0, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setne", "set byte if not equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u0435 \u043d\u043e\u043b\u044c (ZF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnz.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setng", "set byte if not greater", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 1 \u0438\u043b\u0438 SF \u2260 OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setle.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnge", "set byte if not greater or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF \u2260 OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setl.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnl", "set byte if not less", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u0438\u043b\u0438 \u0440\u0430\u0432\u043d\u043e \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (SF = OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setge.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setnle", "set byte if not less or equal", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 \u2014 \u0434\u043b\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445 \u0447\u0438\u0441\u0435\u043b (ZF = 0 \u0438 SF = OF), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setg.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF, SF \u0438 OF", "1, \u0435\u0441\u043b\u0438 \u0431\u043e\u043b\u044c\u0448\u0435 (\u0441\u043e \u0437\u043d\u0430\u043a\u043e\u043c), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("setno", "set byte if not overflow", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0431\u044b\u043b\u043e \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430 (OF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 OF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setnp", "set byte if not parity", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 PF = 0", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0444\u043b\u0430\u0433 \u0447\u0451\u0442\u043d\u043e\u0441\u0442\u0438 PF = 0 (PF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setpo.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 PF", "1, \u0435\u0441\u043b\u0438 PF = 0, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setns", "set byte if not sign", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 (SF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setnz", "set byte if not zero", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043d\u043e\u043b\u044c", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u0435 \u043d\u043e\u043b\u044c (ZF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setne.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "1, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043d\u043e\u043b\u044c, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("seto", "set byte if overflow", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0431\u044b\u043b\u043e \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430 (OF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 OF", "1, \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setp", "set byte if parity", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 PF = 1 (\u0447\u0430\u0441\u0442\u043e: NaN)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0444\u043b\u0430\u0433 \u0447\u0451\u0442\u043d\u043e\u0441\u0442\u0438 PF = 1, \u0430 \u043f\u043e\u0441\u043b\u0435 ucomisd \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e) (PF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setpe.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 PF", "1, \u0435\u0441\u043b\u0438 PF = 1 (\u0447\u0430\u0441\u0442\u043e: NaN), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setpe", "set byte if parity even", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 PF = 1 (\u0447\u0430\u0441\u0442\u043e: NaN)", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0444\u043b\u0430\u0433 \u0447\u0451\u0442\u043d\u043e\u0441\u0442\u0438 PF = 1, \u0430 \u043f\u043e\u0441\u043b\u0435 ucomisd \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e) (PF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setp.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 PF", "1, \u0435\u0441\u043b\u0438 PF = 1 (\u0447\u0430\u0441\u0442\u043e: NaN), \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setpo", "set byte if parity odd", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 PF = 0", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0444\u043b\u0430\u0433 \u0447\u0451\u0442\u043d\u043e\u0441\u0442\u0438 PF = 0 (PF = 0), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: setnp.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 PF", "1, \u0435\u0441\u043b\u0438 PF = 0, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("sets", "set byte if sign", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 (SF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 SF", "1, \u0435\u0441\u043b\u0438 \u043e\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.6");
		rec("setz", "set byte if zero", "", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c 1, \u0435\u0441\u043b\u0438 \u043d\u043e\u043b\u044c", "\u041f\u0438\u0448\u0435\u0442 \u0432 \u0431\u0430\u0439\u0442 1, \u0435\u0441\u043b\u0438 \u0440\u0430\u0432\u043d\u043e, \u0442\u043e \u0435\u0441\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u2014 \u043d\u043e\u043b\u044c (ZF = 1), \u0438\u043d\u0430\u0447\u0435 0. \u0422\u0430\u043a \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u00ab\u0438\u0441\u0442\u0438\u043d\u0430/\u043b\u043e\u0436\u044c\u00bb (5.11). \u0414\u0440\u0443\u0433\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u0442\u043e\u0439 \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438: sete.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 ZF", "1, \u0435\u0441\u043b\u0438 \u043d\u043e\u043b\u044c, \u0438\u043d\u0430\u0447\u0435 0", "5.11,9.8");
		rec("sfence", "store fence", "\u0441\u0442\u043e\u0440 \u0444\u044d\u043d\u0441", "\u0431\u0430\u0440\u044c\u0435\u0440 \u0437\u0430\u043f\u0438\u0441\u0435\u0439", "\u0411\u0430\u0440\u044c\u0435\u0440 \u0434\u043b\u044f \u0437\u0430\u043f\u0438\u0441\u0435\u0439: \u0432\u0441\u0435 \u0437\u0430\u043f\u0438\u0441\u0438 \u0434\u043e \u043d\u0435\u0433\u043e \u0441\u0442\u0430\u043d\u0443\u0442 \u0432\u0438\u0434\u043d\u044b \u0440\u0430\u043d\u044c\u0448\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0445.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0431\u0430\u0440\u044c\u0435\u0440 \u0434\u043b\u044f \u0437\u0430\u043f\u0438\u0441\u0435\u0439", "");
		rec("sgdt", "store global descriptor table register", "\u0441\u0442\u043e\u0440 \u0433\u043b\u043e\u0443\u0431\u044d\u043b \u0434\u0438\u0441\u043a\u0440\u0438\u043f\u0442\u044d\u0440 \u0442\u044d\u0439\u0431\u043b \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b GDT", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c \u0430\u0434\u0440\u0435\u0441 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b GDT (33.7).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0430\u0434\u0440\u0435\u0441 GDT \u0432 \u043f\u0430\u043c\u044f\u0442\u044c", "33.7");
		rec("shl", "shift left", "\u0448\u0438\u0444\u0442 \u043b\u0435\u0444\u0442", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e", "\u0421\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0431\u0438\u0442\u044b \u0432\u043b\u0435\u0432\u043e \u043d\u0430 n: \u044d\u0442\u043e \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 2 \u0432 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 n. shl eax, 3 \u2014 \u0442\u043e \u0436\u0435, \u0447\u0442\u043e eax * 8.", "CF = \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0439 \u0431\u0438\u0442; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e = \u0443\u043c\u043d\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0430 2^n", "10.6");
		rec("shld", "double precision shift left", "\u0434\u0430\u0431\u043b \u043f\u0440\u0438\u0441\u0438\u0436\u043d \u0448\u0438\u0444\u0442 \u043b\u0435\u0444\u0442", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e \u0434\u0432\u043e\u0439\u043d\u043e\u0439 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438", "\u0421\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043f\u0435\u0440\u0432\u044b\u0439 \u043e\u043f\u0435\u0440\u0430\u043d\u0434 \u0432\u043b\u0435\u0432\u043e, \u0430 \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0432\u0448\u0438\u0435\u0441\u044f \u0431\u0438\u0442\u044b \u0431\u0435\u0440\u0451\u0442 \u0438\u0437 \u0432\u0442\u043e\u0440\u043e\u0433\u043e. \u0422\u0430\u043a \u0441\u0434\u0432\u0438\u0433\u0430\u044e\u0442 \u0447\u0438\u0441\u043b\u043e, \u0440\u0430\u0437\u043b\u043e\u0436\u0435\u043d\u043d\u043e\u0435 \u043f\u043e \u0434\u0432\u0443\u043c \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c.", "CF = \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0439 \u0431\u0438\u0442; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043b\u0435\u0432\u043e, \u0431\u0438\u0442\u044b \u0438\u0437 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430", "10.6");
		rec("shr", "shift right", "\u0448\u0438\u0444\u0442 \u0440\u0430\u0439\u0442", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e", "\u0421\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0431\u0438\u0442\u044b \u0432\u043f\u0440\u0430\u0432\u043e \u043d\u0430 n, \u0441\u043b\u0435\u0432\u0430 \u043f\u0440\u0438\u0445\u043e\u0434\u044f\u0442 \u043d\u0443\u043b\u0438: \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 2 \u0432 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 n.", "CF = \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0439 \u0431\u0438\u0442; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e = \u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 2^n (\u0431\u0435\u0437 \u0437\u043d\u0430\u043a\u0430)", "10.6");
		rec("shrd", "double precision shift right", "\u0434\u0430\u0431\u043b \u043f\u0440\u0438\u0441\u0438\u0436\u043d \u0448\u0438\u0444\u0442 \u0440\u0430\u0439\u0442", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e \u0434\u0432\u043e\u0439\u043d\u043e\u0439 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438", "\u0421\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u043f\u0435\u0440\u0432\u044b\u0439 \u043e\u043f\u0435\u0440\u0430\u043d\u0434 \u0432\u043f\u0440\u0430\u0432\u043e, \u0430 \u043e\u0441\u0432\u043e\u0431\u043e\u0434\u0438\u0432\u0448\u0438\u0435\u0441\u044f \u0431\u0438\u0442\u044b \u0431\u0435\u0440\u0451\u0442 \u0438\u0437 \u0432\u0442\u043e\u0440\u043e\u0433\u043e.", "CF = \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0432\u044b\u0442\u043e\u043b\u043a\u043d\u0443\u0442\u044b\u0439 \u0431\u0438\u0442; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0441\u0434\u0432\u0438\u0433 \u0432\u043f\u0440\u0430\u0432\u043e, \u0431\u0438\u0442\u044b \u0438\u0437 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430", "10.6");
		rec("sidt", "store interrupt descriptor table register", "\u0441\u0442\u043e\u0440 \u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442 \u0434\u0438\u0441\u043a\u0440\u0438\u043f\u0442\u044d\u0440 \u0442\u044d\u0439\u0431\u043b \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b IDT", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0432 \u043f\u0430\u043c\u044f\u0442\u044c \u0430\u0434\u0440\u0435\u0441 \u0438 \u0440\u0430\u0437\u043c\u0435\u0440 \u0442\u0430\u0431\u043b\u0438\u0446\u044b IDT (34.4).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0430\u0434\u0440\u0435\u0441 IDT \u0432 \u043f\u0430\u043c\u044f\u0442\u044c", "34.4");
		rec("sqrtpd", "square root packed double", "\u0441\u043a\u0443\u044d\u0430 \u0440\u0443\u0442 \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "\u041a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c, \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("sqrtps", "square root packed single", "\u0441\u043a\u0443\u044d\u0430 \u0440\u0443\u0442 \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "\u041a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c, \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("sqrtsd", "square root scalar double", "\u0441\u043a\u0443\u044d\u0430 \u0440\u0443\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u041a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "12.2");
		rec("sqrtss", "square root scalar single", "\u0441\u043a\u0443\u044d\u0430 \u0440\u0443\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u041a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u044b\u0439 \u043a\u043e\u0440\u0435\u043d\u044c, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "12.2");
		rec("stc", "set carry flag", "\u0441\u044d\u0442 \u043a\u044d\u0440\u0438 \u0444\u043b\u044d\u0433", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0444\u043b\u0430\u0433 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430", "\u0421\u0442\u0430\u0432\u0438\u0442 \u0444\u043b\u0430\u0433 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430: CF = 1.", "CF = 1", "CF = 1", "9.6");
		rec("std", "set direction flag", "\u0441\u044d\u0442 \u0434\u0438\u0440\u044d\u043a\u0448\u043d \u0444\u043b\u044d\u0433", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0444\u043b\u0430\u0433 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f", "\u0421\u0442\u0430\u0432\u0438\u0442 \u0444\u043b\u0430\u0433 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f DF: \u0441\u0442\u0440\u043e\u043a\u043e\u0432\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438 \u043f\u043e\u0439\u0434\u0443\u0442 \u043f\u043e \u043f\u0430\u043c\u044f\u0442\u0438 \u043d\u0430\u0437\u0430\u0434. \u0412\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u0440\u0435\u0434\u043a\u043e.", "DF = 1", "DF = 1: \u0441\u0442\u0440\u043e\u043a\u0438 \u0438\u0434\u0443\u0442 \u043d\u0430\u0437\u0430\u0434", "9.6");
		rec("sti", "set interrupt flag", "\u0441\u044d\u0442 \u0438\u043d\u0442\u044d\u0440\u0430\u043f\u0442 \u0444\u043b\u044d\u0433", "\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0444\u043b\u0430\u0433 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u0439", "\u0420\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0430\u043f\u043f\u0430\u0440\u0430\u0442\u043d\u044b\u0435 \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f (\u0444\u043b\u0430\u0433 IF = 1). \u0422\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u044f\u0434\u0440\u0430 (34.8).", "IF = 1", "\u0440\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u043f\u0440\u0435\u0440\u044b\u0432\u0430\u043d\u0438\u044f (\u044f\u0434\u0440\u043e)", "34.8");
		rec("stos", "store string", "\u0441\u0442\u043e\u0440 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 AL, AX, EAX \u0438\u043b\u0438 RAX \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 RCX \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u2014 \u044d\u0442\u043e memset, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u0441\u0441\u0438\u0432\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0438\u0448\u0435\u0442 AL/AX/EAX/RAX \u0432 [RDI]", "");
		rec("stosb", "store string", "\u0441\u0442\u043e\u0440 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 AL \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI \u043d\u0430 1 \u0431\u0430\u0439\u0442. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 RCX \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u2014 \u044d\u0442\u043e memset, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u0441\u0441\u0438\u0432\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0438\u0448\u0435\u0442 AL \u0432 [RDI]", "");
		rec("stosd", "store string", "\u0441\u0442\u043e\u0440 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 EAX \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI \u043d\u0430 4 \u0431\u0430\u0439\u0442\u0430. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 RCX \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u2014 \u044d\u0442\u043e memset, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u0441\u0441\u0438\u0432\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0438\u0448\u0435\u0442 EAX \u0432 [RDI]", "");
		rec("stosq", "store string", "\u0441\u0442\u043e\u0440 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 RAX \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI \u043d\u0430 8 \u0431\u0430\u0439\u0442. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 RCX \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u2014 \u044d\u0442\u043e memset, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u0441\u0441\u0438\u0432\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0438\u0448\u0435\u0442 RAX \u0432 [RDI]", "");
		rec("stosw", "store string", "\u0441\u0442\u043e\u0440 \u0441\u0442\u0440\u0438\u043d\u0433", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0441\u0442\u0440\u043e\u043a\u0443", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 AX \u0432 [RDI] \u0438 \u0441\u0434\u0432\u0438\u0433\u0430\u0435\u0442 RDI \u043d\u0430 2 \u0431\u0430\u0439\u0442\u0430. \u0421 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c rep \u0437\u0430\u043f\u043e\u043b\u043d\u044f\u0435\u0442 RCX \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u2014 \u044d\u0442\u043e memset, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u043c\u0430\u0441\u0441\u0438\u0432\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0438\u0448\u0435\u0442 AX \u0432 [RDI]", "");
		rec("sub", "subtract", "\u0441\u0430\u0431\u0442\u0440\u044d\u043a\u0442", "\u0432\u044b\u0447\u0435\u0441\u0442\u044c", "sub a, b \u2014 \u044d\u0442\u043e a = a \u2212 b. sub rsp, N \u0432 \u043d\u0430\u0447\u0430\u043b\u0435 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u0432\u044b\u0434\u0435\u043b\u044f\u0435\u0442 \u043c\u0435\u0441\u0442\u043e \u043f\u043e\u0434 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 (11.3).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435 (ZF, SF, CF, OF \u0438 \u0434\u0440\u0443\u0433\u0438\u0435)", "a = a \u2212 b", "10.5");
		rec("subpd", "subtract packed double", "\u0441\u0430\u0431\u0442\u0440\u044d\u043a\u0442 \u043f\u044d\u043a\u0442 \u0434\u0430\u0431\u043b", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "\u0412\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435, \u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430 double \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("subps", "subtract packed single", "\u0441\u0430\u0431\u0442\u0440\u044d\u043a\u0442 \u043f\u044d\u043a\u0442 \u0441\u0438\u043d\u0433\u043b", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "\u0412\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443. \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435, \u0447\u0435\u0442\u044b\u0440\u0435 \u0447\u0438\u0441\u043b\u0430 float \u0441\u0440\u0430\u0437\u0443", "12.2");
		rec("subsd", "subtract scalar double", "\u0441\u0430\u0431\u0442\u0440\u044d\u043a\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "\u0412\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double (8 \u0431\u0430\u0439\u0442). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e double", "12.2");
		rec("subss", "subtract scalar single", "\u0441\u0430\u0431\u0442\u0440\u044d\u043a\u0442 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "\u0412\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u0435\u043b: \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float (4 \u0431\u0430\u0439\u0442\u0430). \u0414\u0440\u043e\u0431\u043d\u044b\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u0432 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438; \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b xmm \u2014 12.2.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u0432\u044b\u0447\u0438\u0442\u0430\u043d\u0438\u0435, \u043e\u0434\u043d\u043e \u0447\u0438\u0441\u043b\u043e float", "12.2");
		rec("swapgs", "swap GS base register", "\u0441\u0432\u043e\u043f \u0434\u0436\u0438-\u044d\u0441 \u0431\u044d\u0439\u0441", "\u043f\u043e\u043c\u0435\u043d\u044f\u0442\u044c \u0431\u0430\u0437\u0443 GS", "\u041c\u0435\u043d\u044f\u0435\u0442 \u043c\u0435\u0441\u0442\u0430\u043c\u0438 \u0431\u0430\u0437\u0443 \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0430 GS \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u0438 \u044f\u0434\u0440\u0430. \u041f\u0435\u0440\u0432\u0430\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f \u044f\u0434\u0440\u0430 \u043f\u043e\u0441\u043b\u0435 syscall (28.5). \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u043e\u043c\u0435\u043d\u044f\u0442\u044c \u0431\u0430\u0437\u0443 GS (\u0432\u0445\u043e\u0434 \u0432 \u044f\u0434\u0440\u043e)", "28.5");
		rec("syscall", "system call", "\u0441\u0438\u0441\u0442\u044d\u043c \u043a\u043e\u043b", "\u0441\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 \u0432\u044b\u0437\u043e\u0432", "\u041f\u0435\u0440\u0435\u0445\u043e\u0434 \u0438\u0437 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b \u0432 \u044f\u0434\u0440\u043e Windows: \u043d\u043e\u043c\u0435\u0440 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 \u044f\u0434\u0440\u0430 \u2014 \u0432 EAX, \u0430\u0434\u0440\u0435\u0441 \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0430 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442 \u0432 RCX, \u0444\u043b\u0430\u0433\u0438 \u2014 \u0432 R11. \u0421\u0442\u043e\u0438\u0442 \u0432 \u043a\u0430\u0436\u0434\u043e\u0439 \u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0435 Nt\u2026 \u0432 ntdll.dll (28.3).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442; RFLAGS \u0443\u0445\u043e\u0434\u0438\u0442 \u0432 R11", "\u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u0432 \u044f\u0434\u0440\u043e (\u043d\u043e\u043c\u0435\u0440 \u0432 EAX)", "28.3,28.5");
		rec("sysret", "return from system call", "\u0440\u0438\u0442\u0451\u0440\u043d \u0444\u0440\u043e\u043c \u0441\u0438\u0441\u0442\u044d\u043c \u043a\u043e\u043b", "\u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u043e\u0433\u043e \u0432\u044b\u0437\u043e\u0432\u0430", "\u0412\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u044f\u0434\u0440\u0430 \u0432 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443 \u043f\u043e\u0441\u043b\u0435 syscall: RIP \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0438\u0437 RCX, \u0444\u043b\u0430\u0433\u0438 \u2014 \u0438\u0437 R11. \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u0438\u0437 R11", "\u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u0438\u0437 \u044f\u0434\u0440\u0430 \u043f\u043e\u0441\u043b\u0435 syscall", "28.5");
		rec("test", "test", "\u0442\u044d\u0441\u0442", "\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c", "\u0414\u0435\u043b\u0430\u0435\u0442 \u043f\u043e\u0431\u0438\u0442\u043e\u0432\u043e\u0435 \u0418, \u043d\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0438\u043a\u0443\u0434\u0430 \u043d\u0435 \u043f\u0438\u0448\u0435\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0444\u043b\u0430\u0433\u0438. test eax, eax \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0430 \u043d\u043e\u043b\u044c: \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 je/jz \u043f\u0440\u044b\u0433\u043d\u0435\u0442, \u0435\u0441\u043b\u0438 EAX = 0.", "CF = OF = 0; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0418 \u0431\u0435\u0437 \u0437\u0430\u043f\u0438\u0441\u0438, \u0442\u043e\u043b\u044c\u043a\u043e \u0444\u043b\u0430\u0433\u0438", "10.7");
		rec("tzcnt", "count trailing zero bits", "\u043a\u0430\u0443\u043d\u0442 \u0442\u0440\u0435\u0439\u043b\u0438\u043d\u0433 \u0437\u0438\u0440\u043e\u0443 \u0431\u0438\u0442\u0441", "\u0441\u043e\u0441\u0447\u0438\u0442\u0430\u0442\u044c \u043d\u0443\u043b\u0438 \u0432 \u043c\u043b\u0430\u0434\u0448\u0438\u0445 \u0431\u0438\u0442\u0430\u0445", "\u0421\u0447\u0438\u0442\u0430\u0435\u0442 \u043d\u0443\u043b\u0435\u0432\u044b\u0435 \u0431\u0438\u0442\u044b \u0441 \u043c\u043b\u0430\u0434\u0448\u0435\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0434\u043e \u043f\u0435\u0440\u0432\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u044b. \u0414\u043b\u044f \u043d\u0443\u043b\u044f \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 \u0434\u0430\u0451\u0442 \u0440\u0430\u0437\u043c\u0435\u0440 \u043e\u043f\u0435\u0440\u0430\u043d\u0434\u0430 \u0432 \u0431\u0438\u0442\u0430\u0445 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 CF = 1.", "CF = 1, \u0435\u0441\u043b\u0438 \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 0; ZF = 1, \u0435\u0441\u043b\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 0", "\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0443\u043b\u0435\u0439 \u0434\u043e \u043f\u0435\u0440\u0432\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u0441\u043d\u0438\u0437\u0443", "");
		rec("ucomisd", "unordered compare scalar double", "\u0430\u043d\u043e\u0440\u0434\u044d\u0434 \u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0434\u0430\u0431\u043b", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0434\u0432\u0430 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u043b\u0430 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u043f\u0440\u0438 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u043c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0438: \u0434\u0430\u043b\u044c\u0448\u0435 \u0438\u0434\u0443\u0442 ja, jb, jae, jbe. PF = 1 \u0437\u043d\u0430\u0447\u0438\u0442 \u00ab\u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b \u2014 NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e)\u00bb, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u044f\u0434\u043e\u043c \u0447\u0430\u0441\u0442\u043e \u0441\u0442\u043e\u0438\u0442 jp.", "ZF, PF, CF \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e; OF = SF = 0", "\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445: \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u0443 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445", "9.8");
		rec("ucomiss", "unordered compare scalar single", "\u0430\u043d\u043e\u0440\u0434\u044d\u0434 \u043a\u044d\u043c\u043f\u0435\u0440 \u0441\u043a\u0435\u0439\u043b\u0430\u0440 \u0441\u0438\u043d\u0433\u043b", "\u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u0430", "\u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u0442 \u0434\u0432\u0430 \u0434\u0440\u043e\u0431\u043d\u044b\u0445 \u0447\u0438\u0441\u043b\u0430 \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u043f\u0440\u0438 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u043e\u043c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0438: \u0434\u0430\u043b\u044c\u0448\u0435 \u0438\u0434\u0443\u0442 ja, jb, jae, jbe. PF = 1 \u0437\u043d\u0430\u0447\u0438\u0442 \u00ab\u043e\u0434\u043d\u043e \u0438\u0437 \u0447\u0438\u0441\u0435\u043b \u2014 NaN (\u043d\u0435 \u0447\u0438\u0441\u043b\u043e)\u00bb, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u044f\u0434\u043e\u043c \u0447\u0430\u0441\u0442\u043e \u0441\u0442\u043e\u0438\u0442 jp.", "ZF, PF, CF \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e; OF = SF = 0", "\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0434\u0440\u043e\u0431\u043d\u044b\u0445: \u0444\u043b\u0430\u0433\u0438 \u043a\u0430\u043a \u0443 \u0431\u0435\u0437\u0437\u043d\u0430\u043a\u043e\u0432\u044b\u0445", "9.8");
		rec("ud2", "undefined instruction", "\u0430\u043d\u0434\u0438\u0444\u0430\u0439\u043d\u0434 \u0438\u043d\u0441\u0442\u0440\u0430\u043a\u0448\u043d", "\u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u0430\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f", "\u041d\u0430\u0440\u043e\u0447\u043d\u043e \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u00ab\u043d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f\u00bb (#UD, 34.2). \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0441\u0442\u0430\u0432\u0438\u0442 \u0435\u0451 \u0442\u0443\u0434\u0430, \u043a\u0443\u0434\u0430 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u043f\u0430\u0441\u0442\u044c \u043d\u0435 \u0434\u043e\u043b\u0436\u043d\u043e.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043d\u0430\u0440\u043e\u0447\u043d\u043e \u043d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f (#UD)", "34.2");
		rec("unpcklpd", "unpack / shuffle / insert / extract (packed)", "\u0430\u043d\u043f\u044d\u043a / \u0448\u0430\u0444\u043b / \u0438\u043d\u0441\u0451\u0440\u0442 / \u044d\u043a\u0441\u0442\u0440\u044d\u043a\u0442", "\u0440\u0430\u0441\u043f\u0430\u043a\u043e\u0432\u0430\u0442\u044c, \u043f\u0435\u0440\u0435\u043c\u0435\u0448\u0430\u0442\u044c, \u0432\u0441\u0442\u0430\u0432\u0438\u0442\u044c, \u0434\u043e\u0441\u0442\u0430\u0442\u044c", "\u041f\u0435\u0440\u0435\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442, \u043f\u0435\u0440\u0435\u043c\u0435\u0448\u0438\u0432\u0430\u0435\u0442, \u0432\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0438\u043b\u0438 \u0434\u043e\u0441\u0442\u0430\u0451\u0442 \u0447\u0430\u0441\u0442\u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430 xmm. \u041e\u0431\u044b\u0447\u043d\u043e \u044d\u0442\u043e \u0441\u043b\u0443\u0436\u0435\u0431\u043d\u0430\u044f \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u0434\u043b\u044f \u0432\u0435\u043a\u0442\u043e\u0440\u043d\u044b\u0445 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0447\u0430\u0441\u0442\u0435\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430 xmm", "12.2");
		rec("vzeroall", "zero all YMM registers", "\u0437\u0438\u0440\u043e\u0443 \u043e\u043b \u0443\u0430\u0439-\u044d\u043c-\u044d\u043c", "\u043e\u0431\u043d\u0443\u043b\u0438\u0442\u044c \u0432\u0441\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b ymm", "\u041e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b ymm (32-\u0431\u0430\u0439\u0442\u043e\u0432\u044b\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b AVX) \u0446\u0435\u043b\u0438\u043a\u043e\u043c.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b ymm \u0446\u0435\u043b\u0438\u043a\u043e\u043c", "12.2");
		rec("vzeroupper", "zero upper bits of YMM registers", "\u0437\u0438\u0440\u043e\u0443 \u0430\u043f\u043f\u044d\u0440 \u0431\u0438\u0442\u0441", "\u043e\u0431\u043d\u0443\u043b\u0438\u0442\u044c \u0432\u0435\u0440\u0445\u043d\u0438\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b ymm", "\u041e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u0432 ymm (32-\u0431\u0430\u0439\u0442\u043e\u0432\u044b\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u044b AVX). \u041a\u043e\u043c\u043f\u0438\u043b\u044f\u0442\u043e\u0440 \u0441\u0442\u0430\u0432\u0438\u0442 \u0435\u0451 \u043f\u0435\u0440\u0435\u0434 \u0432\u044b\u0445\u043e\u0434\u043e\u043c \u0438\u0437 \u0444\u0443\u043d\u043a\u0446\u0438\u0438, \u0433\u0434\u0435 \u0431\u044b\u043b\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u044b AVX.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u0432\u0435\u0440\u0445\u043d\u0438\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b ymm", "12.2");
		rec("wrmsr", "write model-specific register", "\u0440\u0430\u0439\u0442 \u043c\u043e\u0434\u044d\u043b-\u0441\u043f\u044d\u0441\u0438\u0444\u0438\u043a \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u0437\u0430\u043f\u0438\u0441\u0430\u0442\u044c \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u043c\u043e\u0434\u0435\u043b\u0438 (MSR)", "\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u0430\u0440\u0443 EDX:EAX \u0432 \u043e\u0441\u043e\u0431\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043a MSR \u0441 \u043d\u043e\u043c\u0435\u0440\u043e\u043c \u0438\u0437 ECX. \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043b\u044c\u0446\u043e 0.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "EDX:EAX \u2192 MSR[ECX] (\u043a\u043e\u043b\u044c\u0446\u043e 0)", "33.4");
		rec("xadd", "exchange and add", "\u0438\u043a\u0441\u0447\u0435\u0439\u043d\u0434\u0436 \u044d\u043d\u0434 \u044d\u0434", "\u043e\u0431\u043c\u0435\u043d\u044f\u0442\u044c \u0438 \u0441\u043b\u043e\u0436\u0438\u0442\u044c", "\u0421\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442 \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0441\u0442\u0430\u0440\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435: \u043e\u043f\u0435\u0440\u0430\u043d\u0434 \u0432 \u043f\u0430\u043c\u044f\u0442\u0438 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0440\u0435\u0433\u0438\u0441\u0442\u0440, \u0430 \u0432 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0443\u0445\u043e\u0434\u0438\u0442 \u0442\u043e, \u0447\u0442\u043e \u0431\u044b\u043b\u043e \u0432 \u043f\u0430\u043c\u044f\u0442\u0438. \u0421 lock \u2014 \u0430\u0442\u043e\u043c\u0430\u0440\u043d\u044b\u0439 \u0441\u0447\u0451\u0442\u0447\u0438\u043a (\u041f3.4).", "\u043c\u0435\u043d\u044f\u0435\u0442 \u0432\u0441\u0435, \u043a\u0430\u043a add", "[mem] += reg, reg = \u0441\u0442\u0430\u0440\u043e\u0435 [mem]", "\u041f3.4");
		rec("xchg", "exchange", "\u0438\u043a\u0441\u0447\u0435\u0439\u043d\u0434\u0436", "\u043e\u0431\u043c\u0435\u043d\u044f\u0442\u044c", "\u041c\u0435\u043d\u044f\u0435\u0442 \u043c\u0435\u0441\u0442\u0430\u043c\u0438 \u0434\u0432\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f. \u0415\u0441\u043b\u0438 \u043e\u0434\u043d\u043e \u0438\u0437 \u043d\u0438\u0445 \u0432 \u043f\u0430\u043c\u044f\u0442\u0438, \u043e\u0431\u043c\u0435\u043d \u0430\u0442\u043e\u043c\u0430\u0440\u043d\u044b\u0439 \u2014 \u0431\u0443\u0434\u0442\u043e \u0441 \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u043c lock (\u041f3.4).", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043c\u0435\u043d\u044f\u0435\u0442 \u043c\u0435\u0441\u0442\u0430\u043c\u0438 \u0434\u0432\u0430 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f", "\u041f3.4");
		rec("xgetbv", "get value of extended control register", "\u0433\u0435\u0442 \u0432\u044d\u043b\u044c\u044e \u043e\u0432 \u044d\u043a\u0441\u0442\u044d\u043d\u0434\u044d\u0434 \u043a\u043e\u043d\u0442\u0440\u043e\u0443\u043b \u0440\u044d\u0434\u0436\u0438\u0441\u0442\u044d\u0440", "\u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f", "\u0427\u0438\u0442\u0430\u0435\u0442 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f XCR0: \u043a\u0430\u043a\u0438\u0435 \u043d\u0430\u0431\u043e\u0440\u044b \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u0432 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, AVX) \u0432\u043a\u043b\u044e\u0447\u0438\u043b\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u0430. \u0421\u0442\u043e\u0438\u0442 \u0440\u044f\u0434\u043e\u043c \u0441 cpuid, \u043a\u043e\u0433\u0434\u0430 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440\u0430.", "\u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442", "\u043a\u0430\u043a\u0438\u0435 \u043d\u0430\u0431\u043e\u0440\u044b \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u043e\u0432 \u0432\u043a\u043b\u044e\u0447\u0438\u043b\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u0430", "");
		rec("xor", "exclusive or", "\u0438\u043a\u0441\u043a\u043b\u044e\u0437\u0438\u0432 \u043e\u0440", "\u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0435\u0435 \u0418\u041b\u0418", "\u041f\u043e\u0431\u0438\u0442\u043e\u0432\u043e\u0435 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0449\u0435\u0435 \u0418\u041b\u0418. xor eax, eax \u2014 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430 (10.7). \u0414\u0432\u0430\u0436\u0434\u044b \u0441 \u043e\u0434\u043d\u0438\u043c \u043a\u043b\u044e\u0447\u043e\u043c \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u0435: \u043d\u0430 \u044d\u0442\u043e\u043c \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f \u0448\u0438\u0444\u0440 \u0437\u0430\u0434\u0430\u0447\u0438 02 (\u0433\u043b\u0430\u0432\u0430 17).", "CF = OF = 0; ZF \u0438 SF \u043f\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443", "\u0438\u0441\u043a\u043b. \u0418\u041b\u0418; xor eax, eax \u2014 \u043e\u0431\u043d\u0443\u043b\u0435\u043d\u0438\u0435", "10.6,10.7");
