	/** \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0440\u0430\u0437\u0431\u043e\u0440\u0430: \u0437\u0430\u043f\u0438\u0441\u044c, \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u043d\u043e\u0435 \u0438\u043c\u044f, \u043f\u0440\u0435\u0444\u0438\u043a\u0441\u044b, AVX. */
	static final class Resolved {
		String id;
		String shown;
		List<String> prefixes = new ArrayList<>();
		boolean avx;
	}

	static Resolved resolve(String mnem, String text) {
		Resolved res = new Resolved();
		String t = String.join(" ",
			(text == null ? "" : text).replace(",", " ").toLowerCase().trim().split("\\s+"));
		List<String> words = new ArrayList<>(
			Arrays.asList(t.isEmpty() ? new String[0] : t.split(" ")));
		while (!words.isEmpty() && PREFIX_WORDS.contains(words.get(0))) {
			res.prefixes.add(words.remove(0));
		}
		String m = mnem == null ? "" : mnem.trim().toLowerCase();
		if (m.isEmpty() || PREFIX_WORDS.contains(m)) {
			m = words.isEmpty() ? "" : words.get(0);
		}
		String[] parts = m.split("\\.");
		m = parts.length > 0 ? parts[0] : "";
		for (int i = 1; i < parts.length; i++) {
			if (PREFIX_WORDS.contains(parts[i]) && !res.prefixes.contains(parts[i])) {
				res.prefixes.add(parts[i]);
			}
		}
		String operands = words.size() > 1 ? String.join(" ", words.subList(1, words.size())) : "";
		if (!NAMES.containsKey(m) && m.startsWith("v") && m.length() > 1) {
			m = m.substring(1);
			res.avx = true;
		}
		if (m.equals("int") && (operands.equals("3") || operands.equals("03h")
				|| operands.equals("3h") || operands.equals("0x3"))) {
			m = "int3";
		}
		res.shown = m;
		if (m.equals("movsd") || m.equals("cmpsd")) {
			m = m + ((t.contains("xmm") || t.contains("ymm")) ? ".sse" : ".str");
		}
		res.id = NAMES.get(m);
		if (res.id == null && res.avx) {
			res.shown = "v" + res.shown;
		}
		return res;
	}

	static String where(String ch) {
		if (ch.isEmpty()) {
			return "\u0412 \u043a\u0443\u0440\u0441\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043b\u0438. \u041f\u043e\u0434\u0440\u043e\u0431\u043d\u043e\u0441\u0442\u0438 \u2014 \u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 "
				+ "Intel, \u043a\u0430\u043a \u0435\u0451 \u0447\u0438\u0442\u0430\u0442\u044c \u2014 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u041f4.";
		}
		return "\u0413\u0434\u0435 \u0432 \u043a\u0443\u0440\u0441\u0435: " + ch.replace(",", ", ") + ".";
	}

	/** \u0421\u0442\u0440\u043e\u043a\u0438 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 \u0438\u043b\u0438 null, \u0435\u0441\u043b\u0438 \u044d\u0442\u043e \u043d\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f. */
	static List<String> describe(String mnem, String text) {
		Resolved r = resolve(mnem, text);
		if (r.shown == null || r.shown.isEmpty()) {
			return null;
		}
		List<String> lines = new ArrayList<>();
		if (r.id == null) {
			lines.add(r.shown + " \u2014 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0438 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442.");
			lines.add("\u0414\u043e\u0431\u0430\u0432\u044c \u0435\u0451 \u0432 \u0431\u0430\u0437\u0443 (tools/hints, \u0441\u043a\u0438\u043b\u043b ru-hints) \u0438\u043b\u0438 \u043d\u0430\u0439\u0434\u0438 "
				+ "\u0432 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 Intel (\u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u041f4).");
			return lines;
		}
		String[] rec = RECORDS.get(r.id);
		String say = rec[1].isEmpty() ? "" : " [" + rec[1] + "]";
		lines.add((r.avx ? "v" + r.shown : r.shown) + " \u2014 " + rec[0] + say + ", \u00ab" + rec[2] + "\u00bb");
		if (r.avx) {
			lines.add("\u0411\u0443\u043a\u0432\u0430 v \u0432\u043f\u0435\u0440\u0435\u0434\u0438 \u2014 \u043d\u043e\u0432\u0430\u044f \u0444\u043e\u0440\u043c\u0430 AVX: \u0442\u043e \u0436\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 "
				+ "\u043d\u0430\u0434 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u043c\u0438 xmm \u0438\u043b\u0438 ymm (32 \u0431\u0430\u0439\u0442\u0430).");
		}
		lines.add(rec[3]);
		lines.add("\u0424\u043b\u0430\u0433\u0438: " + rec[4] + ".");
		for (String p : r.prefixes) {
			if (PREFIXES.containsKey(p)) {
				lines.add("\u041f\u0440\u0435\u0444\u0438\u043a\u0441 " + PREFIXES.get(p));
			}
		}
		lines.add(where(rec[6]));
		return lines;
	}

	static String shortComment(String mnem, String text) {
		Resolved r = resolve(mnem, text);
		if (r.id == null) {
			return null;
		}
		String[] rec = RECORDS.get(r.id);
		StringBuilder head = new StringBuilder();
		for (String p : r.prefixes) {
			head.append(p).append(' ');
		}
		head.append(r.avx ? "v" + r.shown : r.shown);
		String ch = rec[6];
		String tail = ch.isEmpty() ? "" : " (" + ch.split(",")[0] + ")";
		return MARK + head + " \u2014 " + rec[5] + tail;
	}

